// 科目一精简500题 · 题库数据（由《驾考精简500题》PDF 提取）
window.QUESTIONS = [{"id":0,"type":"单选题","question":"如图所示，遇到这种单方交通事故，应当如何处理？","options":["不用报警","报警","直接联系路政部门进行理赔","直接联系绿化部门"],"answer":[1],"image":"img/q000.jpg","tip":"","explanation":"图中虽然是单方交通事故，但由于车辆撞到了隔离带，涉及到公共财产损坏，需要立即报警，找交警协助处理。"},{"id":1,"type":"单选题","question":"行车中遇交通事故受伤者需要抢救时，应怎样做？","options":["及时将伤者送医院抢救或拨打急救电话","尽量避开，少惹麻烦","绕过现场行驶","借故避开现场"],"answer":[0],"image":null,"tip":"伸出您的援手，爱心传递你我他。所以选“及时将伤者送医院抢救或拨打急救电话”。","explanation":"遇到交通事故需要抢救伤员时，要提供力所能及的帮助，将伤者送往医院或拨打急救电话。选项中“避开”、“绕过”都是不提倡的行为。"},{"id":2,"type":"单选题","question":"机动车之间发生交通事故造成轻微财产损失，当事人对事实及成因无争议时，在确保安全的原则下，对现场拍照或标划事故车辆现场位置后，可自行撤离现场处理损害赔偿事宜，主要目的是什么？","options":["双方互有损失","找现场证人就行了，不必报警","为了及时恢复交通，避免造成交通拥堵","事故后果很小，无需赔偿"],"answer":[2],"image":null,"tip":"轻微财产损失事故，协商无争议，尽快撤离不要影响其他车辆。所以选“避免造成交通拥堵”。","explanation":"发生轻微财产损失事故，无伤亡，无争议的，可先拍照撤离再协商解决，尽快恢复交通，以防造成拥堵。"},{"id":3,"type":"单选题","question":"发生无人员伤亡的、财产轻微损失的交通事故后，以下做法正确的是什么？","options":["必须报警，等候警察处理","开车离开现场","确保安全的情况下，对现场拍照，然后将车辆移至路边等不妨碍交通的地点","停在现场保持不动"],"answer":[2],"image":null,"tip":"发生无人员伤亡、财产轻微损失的事故，不得妨碍交通。所以选“确保安全的情况下，对现场拍照，然后将车辆移至路边等不妨碍交通的地点”。","explanation":"发生无人员伤亡、财产轻微损失的事故，要先拍照取证，再将车转移到不妨碍交通的位置，自行协商解决。"},{"id":4,"type":"单选题","question":"下列交通违法行为，一次记9分的是什么？","options":["驾驶机动车在城市快速路上违法停车的","驾驶载货汽车违反规定载客的","驾驶机动车在高速公路上穿越中央分隔带掉头的","驾驶机动车在高速公路上逆行的"],"answer":[0],"image":null,"tip":"","explanation":"驾驶机动车在城市快速路上违法停车的，一次记9分。"},{"id":5,"type":"单选题","question":"车辆因故障等原因需被牵引时，以下说法正确的是什么？","options":["前后车均应打开报警灯","所有车辆都应让行","两车尽量快速行驶","不受交通信号限制"],"answer":[0],"image":"img/q005.jpg","tip":"","explanation":"车辆因故障被牵引时，前后车均应开启危险报警闪光灯，以示意其他车辆。"},{"id":6,"type":"单选题","question":"机动车驾驶人由摩托车类准驾车型增加汽车类准驾车型后的多长时间为实习期？","options":["2年","3个月","12个月","6个月"],"answer":[2],"image":null,"tip":"","explanation":"初次取得汽车类和摩托车类车型的实习期都是12个月。"},{"id":7,"type":"单选题","question":"驾驶机动车发生交通事故未造成人身伤亡的，责任明确双方无争议时，应当如何处置？","options":["保护好现场再协商","不要移动车辆","疏导其他车辆绕行","撤离现场自行协商"],"answer":[3],"image":null,"tip":"看文字答题，题干中有“自行协商”，就在选项中找“无争议”。题干中见到“无争议”，选项中找“自行协商”。","explanation":"未造成人员伤亡，且双方无争议的，就要尽快撤离现场自行协商解决，以免造成交通拥堵。"},{"id":8,"type":"单选题","question":"发生交通事故时，下列哪种情况下当事人应当保护现场并立即报警？","options":["未造成人员伤亡的","未发生财产损失事故","未损害公共设施及建筑物的","驾驶人有酒后驾驶嫌疑的"],"answer":[3],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"驾驶人有酒驾嫌疑的，因为涉嫌违法，需要保护现场立即报警，找交警协助处理。"},{"id":9,"type":"单选题","question":"驾驶机动车发生交通事故，仅造成财产损失的，但是对交通事故事实及成因有争议的，应当怎么处理？","options":["迅速报警","占道继续和对方争辩","找中间人帮忙解决","自行协商损害赔偿事宜"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"发生交通事故，凡是双方有争议的，就要立即报警，让交警协助处理。"},{"id":10,"type":"单选题","question":"驾驶机动车发生交通事故后当事人故意破坏、伪造现场、毁灭证据的，应当承担什么责任？","options":["主要责任","次要责任","同等责任","全部责任"],"answer":[3],"image":null,"tip":"判责：非故意都负责；故意、不礼让的负全责；掉货物的负全责。","explanation":"凡是逃逸、故意破坏，伪造现场、毁灭证据的，都要承担全部责任。"},{"id":11,"type":"单选题","question":"驾驶机动车发生以下交通事故，哪种情况适用自行协商解决？","options":["对方饮酒的","对事实及成因有争议的","未造成人身伤亡，对事实及成因无争议的","造成人身伤亡的"],"answer":[2],"image":null,"tip":"看文字答题，题干中有“自行协商”，就在选项中找“无争议”。题干中见到“无争议”，选项中找“自行协商”。","explanation":"发生交通事故，无争议无伤亡的可自行协商解决，有争议或有伤亡的要找交警协助处理。"},{"id":12,"type":"单选题","question":"在道路上发生未造成人员伤亡且无争议的轻微交通事故如何处置？","options":["保护好现场再协商","不要移动车辆","疏导其他车辆绕行","撤离现场自行协商"],"answer":[3],"image":null,"tip":"看文字答题，题干中有“自行协商”，就在选项中找“无争议”。题干中见到“无争议”，选项中找“自行协商”。","explanation":"无人员伤亡且无争议的轻微事故，可即行撤离现场，自行协商解决，以免造成交通拥堵。"},{"id":13,"type":"单选题","question":"行车中遇有前方发生交通事故，需要帮助时，应怎样做？","options":["尽量绕道躲避","立即报警，停车观望","协助保护现场，并立即报警","加速通过，不予理睬"],"answer":[2],"image":null,"tip":"路遇事故，抢救报警，标明位置。","explanation":"当他人发生事故需要帮助时，一定要伸出援手，协助保护现场，并立即报警。"},{"id":14,"type":"单选题","question":"在道路上驾驶机动车追逐竞驶，情节恶劣的，或者在道路上醉酒驾驶机动车的如何处罚？","options":["3年以下有期徒刑","7年以下有期徒刑","处拘役，并处罚金","10年以下有期徒刑"],"answer":[2],"image":null,"tip":"20到80是酒驾：扣12分；80以上是醉驾：拘役罚款。","explanation":"在道路上行车，追逐竞驶，情节恶劣，或醉酒驾驶的，处拘役并处罚金。"},{"id":15,"type":"单选题","question":"下列哪种证件是驾驶机动车上路行驶应当随车携带？","options":["机动车登记证","机动车保险单","机动车行驶证","出厂合格证明"],"answer":[2],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"驾驶机动车应随车携带机动车行驶证、驾驶证，无论是电子版，还是纸质版，都需要随车携带。"},{"id":16,"type":"单选题","question":"机动车驾驶人在一个记分周期内累积记分达到多少分的，公安机关交通管理部门将通知其参加满分学习、考试？","options":["6分","9分","12分","24分"],"answer":[2],"image":null,"tip":"满分学习并考试，拒不参加证停用。","explanation":"一个记分周期记满12分的，要参加满分学习、考试。"},{"id":17,"type":"单选题","question":"申请轻型牵引挂车准驾车型的，年龄应满多少周岁？","options":["22周岁","19周岁","18周岁","20周岁"],"answer":[3],"image":null,"tip":"","explanation":"轻型牵引挂车即C6，申请年龄限于20-60。"},{"id":18,"type":"单选题","question":"下列关于同一机动车所有人名下两辆机动车的号牌号码互换，以下说法正确的是什么？","options":["同一机动车一年内可以多次互换变更机动车号牌号码","两辆机动车使用性质非营运可以申请互换","申请前两车无未处理的道路交通安全违法和交通事故记录","两辆机动车在不同辖区车辆管理所登记可以申请互换"],"answer":[2],"image":null,"tip":"","explanation":"申请前两车无未处理的道路交通安全违法和交通事故记录， 同一机动车所有人名下机动车的号牌可以申请互换。"},{"id":19,"type":"单选题","question":"驾驶人未携带哪种证件驾驶机动车上路，交通警察可依法扣留车辆？","options":["机动车驾驶证","居民身份证","从业资格证","机动车通行证"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"驾驶机动车应随车携带机动车行驶证、驾驶证，无论是电子版，还是纸质版，都需要随车携带。"},{"id":20,"type":"单选题","question":"上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？","options":["未携带身份证","未放置城市环保标志","未携带机动车登记证书","未携带行驶证"],"answer":[3],"image":null,"tip":"","explanation":"未携带行驶证会被扣留车辆。"},{"id":21,"type":"单选题","question":"使用伪造、变造的机动车号牌的，一次记几分？","options":["3分","6分","9分","12分"],"answer":[3],"image":null,"tip":"","explanation":"凡是使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的，都一次记12分。"},{"id":22,"type":"单选题","question":"关于机动车号牌灭失、丢失或者损毁的，以下说法错误的是什么？","options":["机动车所有人应当向登记地车辆管理所申请补领、换领","补领、换领机动车号牌的，原机动车号牌可以继续使用","车辆管理所补发、换发号牌，原机动车号牌号码不变","补发、换发号牌期间，申请人可以申领有效期不超过十五日的临时行驶车号牌"],"answer":[1],"image":null,"tip":"","explanation":"补领、换领机动车号牌的，原机动车号牌不得再使用。"},{"id":23,"type":"单选题","question":"机动车驾驶人血液中酒精含量大于或者等于多少可认定为醉驾？","options":["20毫克/100毫升","60毫克/100毫升","80毫克/100毫升","50毫克/100毫升"],"answer":[2],"image":null,"tip":"20到80是酒驾：扣12分；80以上是醉驾：拘役罚款。","explanation":"血液中酒精含量≥80mg/100ml，属于醉酒驾驶；血液中酒精含量大于或等于20mg/100ml，小于80mg/100ml，属于饮酒驾驶。"},{"id":24,"type":"单选题","question":"以下哪项行为可构成危险驾驶罪？","options":["闯红灯","无证驾驶","疲劳驾驶","醉驾"],"answer":[3],"image":null,"tip":"危险驾驶罪：竞驶或醉驾，处拘役罚金。","explanation":"醉驾和追逐竞驶，情节恶劣的，可构成危险驾驶罪。"},{"id":25,"type":"单选题","question":"驾驶拼装机动车上路行驶的驾驶人，除按规定接受罚款外，还要受到哪种处理？","options":["处10日以下拘留","暂扣驾驶证","吊销驾驶证","追究刑事责任"],"answer":[2],"image":null,"tip":"驾驶拼装、报废车上路，罚款两百至两千，并处吊销驾照，所以选“吊销驾驶证”。","explanation":"驾驶拼装车上路有安全隐患，将罚款200-2000元，吊销驾驶证，收缴车辆并强制报废。"},{"id":26,"type":"单选题","question":"驾驶达到报废标准的机动车上道路行驶的，公安交通管理部门将会予以收缴。以下说法错误的是什么？","options":["驾驶报废车影响驾驶人行车安全","报废车机械老化、容易发生交通事故","车辆不符合安全技术标准，需要强制报废","不美观，影响城市形象"],"answer":[3],"image":null,"tip":"已经达到报废标准的车辆性能方面具有安全隐患，会影响驾驶，不得上路行驶，题干问说法错误的，所以选“不美观，影响城市形象”。","explanation":"公安交通管理部门收缴上路的报废车，是因为报废车严重老化非常危险，与不美观无关。"},{"id":27,"type":"单选题","question":"年龄在70周岁以上的机动车驾驶人，相关法律规定应当多长时间进行一次身体检查并提交身体条件证明？","options":["无需体检","每半年","每两年","每年"],"answer":[3],"image":null,"tip":"","explanation":"70周岁以上每年要体检。"},{"id":28,"type":"单选题","question":"在学习驾驶证明的有效期内，科目二和科目三道路驾驶技能考试预约次数分别不得超过多少次？","options":["3次","4次","5次","6次"],"answer":[2],"image":null,"tip":"","explanation":"科目二和科目三只有5次考试机会，有效期3年，从科目一考试合格后开始算起。"},{"id":29,"type":"单选题","question":"机动车驾驶人处理完交通违法行为记录后累积记分未满12分，参加公安机关交通管理部门组织的交通安全教育并达到规定要求的，可以申请在机动车驾驶人现有累积记分分值中扣减记分。在一个记分周期内累计最高扣减几分？","options":["3分","6分","5分","12分"],"answer":[1],"image":null,"tip":"","explanation":"参加学法减分，一个记分周期累计最高减6分。"},{"id":30,"type":"单选题","question":"驾驶人因服兵役、出国（境）等原因无法办理审验时，延期审验期限最长不超过多长时间？","options":["1年","2年","3年","5年"],"answer":[2],"image":null,"tip":"兵役、出国无法审验，延期3年，期间禁驾。","explanation":"因服兵役、出国（境）无法审验驾驶证的，可申请延期，延期期限最长不超过三年，且期间不得驾驶机动车。"},{"id":31,"type":"单选题","question":"以欺骗、贿赂等不正当手段取得驾驶证被依法撤销驾驶许可的，多长时间不得重新申请驾驶许可？","options":["3年内","终生","1年内","5年内"],"answer":[0],"image":null,"tip":"","explanation":"驾驶证被撤销的，3年内不得重新申领（假一吊二撤三醉五逃终生）。"},{"id":32,"type":"判断题","question":"机动车之间发生交通事故，不管是否有人员伤亡，只要双方当事人同意，都可自行协商解决。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“是否”就选错。（例外情况1题：当出现“燃油”时选对）","explanation":"发生交通事故，无伤亡、无争议的，可先撤离再协商解决。有伤亡、有争议的，需要立即报警请交警协助处理。"},{"id":33,"type":"判断题","question":"在道路上发生交通事故造成人身伤亡时，要立即抢救受伤人员并迅速报警。","options":["正确","错误"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"第一时间要抢救伤员，并迅速报警。如因抢救伤员变动现场时要标明位置。"},{"id":34,"type":"单选题","question":"以下哪种情形会被扣留车辆？","options":["未安装防撞装置","车内装饰过多，影响驾驶人视线","未携带行驶证","驾驶人开车打电话"],"answer":[2],"image":null,"tip":"","explanation":"不带行驶证会被扣留车辆。"},{"id":35,"type":"单选题","question":"下列交通违法行为，一次记12分的是什么？","options":["驾驶机动车在城市快速路上倒车的","连续驾驶中型以上载客汽车、危险物品运输车超过4小时未停车休息的","驾驶机动车在高速公路或者城市快速路上违法占用应急车道行驶的","机动车驾驶证被暂扣或者扣留期间驾驶机动车的"],"answer":[0],"image":null,"tip":"","explanation":"驾驶机动车在城市快速路上倒车的，一次记12分。"},{"id":36,"type":"单选题","question":"3年内有下列哪种行为的人不得申请机动车驾驶证？","options":["吸烟成瘾","吸食、注射毒品","注射胰岛素","酒醉经历"],"answer":[1],"image":null,"tip":"","explanation":"有吸食、注射毒品行为的三年内不得申请驾驶证。其他选项中，吸烟成瘾危害健康、注射胰岛素是为降低血糖、有酒醉经历而不是醉驾经历，都可申请机动车驾驶证。"},{"id":37,"type":"单选题","question":"实习期驾驶人驾驶机动车上高速公路行驶，以下做法正确的是什么？","options":["任何情况下都不允许上高速","不需要其他人员陪同","需要持有相应或者更高准驾车型驾驶证三年以上的驾驶人陪同","需要持有相应或者更高准驾车型驾驶证、同在实习期内的驾驶人陪同"],"answer":[2],"image":null,"tip":"","explanation":"实习期驾驶员驾驶技术还处在入门阶段，不得单独驾车上高速公路，要由驾龄三年以上的老司机陪同。"},{"id":38,"type":"单选题","question":"交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪？","options":["无驾驶资格驾驶机动车辆的","未报警","未带驾驶证","未抢救受伤人员"],"answer":[0],"image":null,"tip":"","explanation":"1.酒驾或毒驾；2.无驾驶资格驾车；3.车辆有安全隐患；4.无牌车或报废车；5.严重超载；6.肇事逃逸。具有以上任意一种行为，且致人重伤，负全部或主要责任的，都是交通肇事罪。"},{"id":39,"type":"单选题","question":"参加公安机关交通管理部门组织的交通安全公益活动的，满几小时为一次，一次扣减几分？","options":["2小时；2分","1小时；1分","2小时；1分","1小时；2分"],"answer":[1],"image":null,"tip":"","explanation":"参加安全公益活动的，满1小时减1分。"},{"id":40,"type":"单选题","question":"以下哪种情形不会被扣留车辆？","options":["未按规定悬挂号牌","未按规定购买第三者责任强制保险","未随车携带灭火器","未随车携带行驶证"],"answer":[2],"image":null,"tip":"","explanation":"上道路行驶的机动车未携带灭火器，不会被扣留车辆。"},{"id":41,"type":"单选题","question":"上道路行驶的机动车驾驶人未携带机动车驾驶证、行驶证的，除扣留机动车外，并受到什么处罚？","options":["警告","罚款","拘留","吊销驾驶证"],"answer":[1],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"驾驶机动应随车携带行驶证、驾驶证，纸质版或者电子版均可，否则会处以罚款。"},{"id":42,"type":"单选题","question":"以下不属于机动车驾驶证审验内容的是什么？","options":["道路交通安全违法行为、交通事故处理情况","驾驶人身体条件","记满12分后参加学习和考试情况","驾驶车辆累计行驶里程"],"answer":[3],"image":null,"tip":"车辆审验查车，驾照审验查人。","explanation":"驾驶证审验与机动车无关，不包含车辆累计行驶里程。注意题干问的是“不属于”。"},{"id":43,"type":"单选题","question":"超过机动车驾驶证有效期一年以上未换证被注销，但未超过2年的，机动车驾驶人应当如何恢复驾驶资格？","options":["参加道路交通安全法律、法规和相关知识考试合格后","参加场地考试合格后","参加道路驾驶技能考试合格后","参加安全文明驾驶常识考试合格后"],"answer":[0],"image":null,"tip":"超期被注销，两年内考科一可重领。","explanation":"驾驶证被注销一年以上不满两年的，只需重考科目一，合格后方可恢复。科目一是道路交通安全法律、法规和相关知识考试。"},{"id":44,"type":"单选题","question":"以下哪种身体条件，不可以申请机动车驾驶证？","options":["糖尿病","红绿色盲","高血压","怀孕"],"answer":[1],"image":null,"tip":"疾病影响驾驶，禁止申领驾照。","explanation":"红绿色盲分不清红绿灯，容易引发交通事故，不可申请驾驶证。其他选项糖尿病、高血压、怀孕，均可申请。"},{"id":45,"type":"单选题","question":"机动车购买后尚未注册登记，需要临时上道路行驶的，可以凭什么临时上道路行驶？","options":["合法来源凭证","临时行驶车号牌","借用的机动车号牌","法人单位证明"],"answer":[1],"image":null,"tip":"车未注册申临牌，方可临时上路行。","explanation":"未注册登记的机动车，要有临时通行牌证，才能上路。"},{"id":46,"type":"单选题","question":"机动车驾驶人违法驾驶造成重大交通事故构成犯罪的，依法追究什么责任？","options":["刑事责任","民事责任","经济责任","直接责任"],"answer":[0],"image":null,"tip":"犯罪了当然要承担刑事责任，所以选“刑事责任”。","explanation":"造成重大事故且构成犯罪的，都将依法追究刑事责任。"},{"id":47,"type":"单选题","question":"年龄在70周岁以上的机动车驾驶人，应当每年进行一次身体检查的目的是什么？","options":["体现对老年人的关心","例行程序仅供参考","检查是否患有老年常见病","检查是否患有妨碍安全驾驶的疾病"],"answer":[3],"image":null,"tip":"驾驶人体检，一切为了安全考虑。","explanation":"70周岁以上属于高龄驾驶员，每年提交身体证明，目的是检查是否患有妨碍安全驾驶的疾病，为自己也为他人安全着想。"},{"id":48,"type":"单选题","question":"道路交通违法行为累积记分周期是多长时间？","options":["14个月","12个月","10个月","6个月"],"answer":[1],"image":null,"tip":"累积记分制度，周期12个月，满分12分。","explanation":"累积记分周期是一年，12个月，满分12分，从驾驶证初次领取日算起。"},{"id":49,"type":"判断题","question":"在道路上造成人身伤亡、事故后果非常严重的交通事故，可自行撤离现场。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“伤亡”就选错。（例外情况4题：当出现“报警”、“无争议”时选对）","explanation":"只有无伤亡、无争议的轻微事故，才可先撤离再协商；有伤亡、有争议的，要立即报警，等待交警协助处理。"},{"id":50,"type":"单选题","question":"驾驶机动车应当随身携带哪种证件？","options":["工作证","驾驶证","身份证","职业资格证"],"answer":[1],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"驾驶机动车应随车携带机动车行驶证、驾驶证，无论是电子版，还是纸质版，都需要随车携带。"},{"id":51,"type":"单选题","question":"申请人在机动车驾驶人考试过程中组织作弊的，情节严重构成犯罪的，会受到什么处罚？","options":["处三年以上七年以下有期徒刑，并处罚金","处三年以下有期徒刑，并处罚金","处管制，并处罚金","处七年以上有期徒刑，并处罚金"],"answer":[0],"image":null,"tip":"","explanation":"组织作弊，情节严重，处三年以上七年以下有期徒刑，并处罚金。"},{"id":52,"type":"单选题","question":"下列交通违法行为，一次记1分的是什么？","options":["驾驶校车在高速公路、城市快速路以外的道路上行驶超过规定时速百分二十以上未达到百分之五十的","驾驶机动车不按规定超车、让行","驾驶机动车在高速公路或者城市快速路上违法停车的","驾驶机动车不按规定使用灯光的"],"answer":[3],"image":null,"tip":"","explanation":"不按规定使用灯光，扣1分。"},{"id":53,"type":"单选题","question":"申请小型汽车准驾车型驾驶证的人年龄条件是多少？","options":["16周岁以上","18周岁以上","21周岁以上","24周岁以上"],"answer":[1],"image":null,"tip":"","explanation":"申请小型汽车驾驶证年龄：18周岁以上不设上限。不同准驾车型，申请年龄不同，注意看清题干。"},{"id":54,"type":"单选题","question":"交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪？","options":["未带驾驶证","未报警","明知是安全装置不全或者安全机件失灵的机动车辆而驾驶的","未抢救受伤人员的"],"answer":[2],"image":null,"tip":"","explanation":"1.酒驾或毒驾；2.无驾驶资格驾车；3.车辆有安全隐患；4.无牌车或报废车；5.严重超载；6.肇事逃逸。具有以上任意一种行为，且致人重伤，负全部或主要责任的，都是交通肇事罪。"},{"id":55,"type":"单选题","question":"使用伪造、变造的行驶证、驾驶证的，一次记几分？","options":["12分","6分","3分","9分"],"answer":[0],"image":null,"tip":"","explanation":"凡是使用“伪造、变造的”，无论是机动车号牌、行驶证、驾驶证、校车标牌，都一次记12分。"},{"id":56,"type":"单选题","question":"未取得校车驾驶资格驾驶校车的，一次记几分？","options":["12分","9分","6分","3分"],"answer":[1],"image":null,"tip":"","explanation":"未取得校车资格驾驶校车，一次记9分。"},{"id":57,"type":"单选题","question":"申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，会受到什么处罚？","options":["处两千元以下罚款，申请人在三年内不得再次申领机动车驾驶证","申请人在一年内不得再次申领机动车驾驶证","处五百元以下罚款，申请人在三年内不得再次申领机动车驾驶证","处五百元以下罚款"],"answer":[0],"image":null,"tip":"","explanation":"以欺骗、贿赂取得驾驶证，罚款2000元以下，三年内不得再次申领。"},{"id":58,"type":"单选题","question":"关于交通违法行为，以下说法错误的是什么？","options":["造成致人轻微伤或者财产损失的交通事故后逃逸，尚不构成犯罪的，一次记9分","驾驶机动车在高速公路上违法占用应急车道行驶的，一次记6分","驾驶机动车在高速公路或者城市快速路上违法停车的，一次记9分","机动车驾驶证被暂扣或扣留期间驾驶机动车的，一次记6分"],"answer":[0],"image":null,"tip":"","explanation":"造成致人轻微伤或者财产损失的交通事故后逃逸，尚不构成犯罪的，一次记6分，不是9分。"},{"id":59,"type":"单选题","question":"驾驶7座以上载客汽车载人超过核定人数百分之二十以上未达到百分之五十的，一次记几分？","options":["9分","3分","12分","6分"],"answer":[3],"image":null,"tip":"","explanation":"7座以上载客汽车超过核载人数20%-50%之间，一次记6分。"},{"id":60,"type":"单选题","question":"下列哪种情况可以向机动车驾驶证核发地车辆管理所申请补发？","options":["驾驶证被扣押","驾驶证被扣留","驾驶证遗失","驾驶证被暂扣"],"answer":[2],"image":null,"tip":"","explanation":"驾驶证遗失、损毁的，需申请补发；扣留、扣押及暂扣的说明有违法行为，都不得补发。"},{"id":61,"type":"单选题","question":"驾驶人出现下列哪种情况，不得驾驶机动车？","options":["驾驶证丢失、损毁","驾驶证接近有效期","记分达到10分","记分达到6分"],"answer":[0],"image":null,"tip":"","explanation":"驾驶证丢失、损毁的应当申请补发、换证，在此期间不得驾驶机动车。"},{"id":62,"type":"单选题","question":"提供虚假材料申领驾驶证的申请人会承担下列哪种法律责任？","options":["处20元以上200元以下罚款","取消申领驾驶证资格","1年内不得再次申领驾驶证","2年内不能再次申领驾驶证"],"answer":[2],"image":null,"tip":"","explanation":"提供虚假材料申领驾驶证的，一年内不得再次申领。（假一吊二撤三醉五逃终生）"},{"id":63,"type":"单选题","question":"关于醉酒驾驶机动车的处罚，以下说法错误的是什么？","options":["公安机关交通管理部门约束至酒醒","吊销驾驶证","五年内不得重新取得机动车驾驶证","记6分"],"answer":[3],"image":null,"tip":"醉驾很严重，扣12分！注意是问错误的。所以选“记6分”。","explanation":"醉酒驾车后果严重，理应重罚，酒醒后要扣12分，吊销驾驶证，依法追究刑事责任，五年内不得重新取得机动车驾驶证。注意是选“错误的”。"},{"id":64,"type":"单选题","question":"驾驶证审验内容不包括以下哪一项？","options":["道路交通安全违法行为、交通事故处理情况","身体条件情况","道路交通安全违法行为记分及记满12分后参加学习和考试情况","机动车检验情况"],"answer":[3],"image":null,"tip":"车辆审验查车，驾照审验查人。","explanation":"有驾驶证的不一定有车，所以驾驶证审验不包括机动车检验。"},{"id":65,"type":"单选题","question":"驾驶机动车在道路上违反道路交通安全法的行为，属于什么行为？","options":["违章行为","违法行为","过失行为","违规行为"],"answer":[1],"image":null,"tip":"扣分的都是违法行为，影响驾驶的是陋习。","explanation":"道路交通安全法是法，违反当然属于违法行为。"},{"id":66,"type":"判断题","question":"非机动车驾驶人、行人故意碰撞机动车造成交通事故的，机动车一方不承担赔偿责任。","options":["正确","错误"],"answer":[0],"image":null,"tip":"看文字答题，题干中见到“责任”就选对。（例外情况5题：当出现“不追究”、“自行”、“不得”或“伤亡”时选错）","explanation":"非机动车和行人故意碰撞机动车的属于碰瓷，机动车一方不承担赔偿责任。"},{"id":67,"type":"单选题","question":"醉酒驾驶机动车在道路上行驶会受到什么处罚？","options":["处2年以下徒刑","处拘役，并处罚金","处2年以上徒刑","处管制，并处罚金"],"answer":[1],"image":null,"tip":"20到80是酒驾：扣12分；80以上是醉驾：拘役罚款。","explanation":"醉酒驾驶机动车要处拘役，并处罚金。此外还会吊销驾驶证，五年内不得再次申领。"},{"id":68,"type":"单选题","question":"驾驶机动车在道路上追逐竞驶，情节恶劣，会受到什么处罚？","options":["处拘役，并处罚金","处管制，并处罚金","处1年以上徒刑","处6个月徒刑"],"answer":[0],"image":null,"tip":"看文字答题，选项中见到“拘役”可直接选。","explanation":"在道路上追逐竞驶，情节恶劣的，要处拘役，并处罚金。"},{"id":69,"type":"单选题","question":"存在以下哪种行为的申请人在一年内不得再次申领机动车驾驶证？","options":["在考试过程中出现身体不适","在考试过程中有舞弊行为","不能按照教学大纲认真练习驾驶技能","未参加理论培训"],"answer":[1],"image":null,"tip":"假一骗三。","explanation":"考试中有舞弊行为的，属于造假的一种，一年内不可再次申领驾驶证。（假一吊二撤三醉五逃终生）"},{"id":70,"type":"判断题","question":"驾驶机动车发生财产损失交通事故后，当事人对事实及成因无争议移动车辆时需要对现场拍照或者标划停车位置。","options":["正确","错误"],"answer":[0],"image":null,"tip":"财产损失事故，协商无争议，拍好照片，快点撤离，避免拥堵。","explanation":"发生交通事故，无伤亡、无争议的，可先撤离再协商解决。为留存证据，当事人要在移动车辆前对现场拍照或标划停车位置。"},{"id":71,"type":"单选题","question":"机动车驾驶证补领后，以下说法正确的是什么？","options":["原驾驶证继续使用","原驾驶证作废，不得继续使用","原驾驶证特殊情况下使用","替换使用"],"answer":[1],"image":null,"tip":"除旧迎新，办理新证之后旧证不能继续使用。","explanation":"驾驶证补领一般是证件遗失或损坏，领了新的自然原来的就作废，防止被其他不法分子利用。"},{"id":72,"type":"单选题","question":"驾驶人有哪种情形，交通警察可依法扣留机动车驾驶证？","options":["饮酒后驾驶机动车","超过规定速度10%","疲劳后驾驶机动车","行车中未系安全带"],"answer":[0],"image":null,"tip":"酒驾暂扣6个月，再次酒驾就吊销、禁止申领AB照。","explanation":"初次饮酒后驾车，暂扣6个月驾驶证，并处1000-2000元罚款；再次饮酒后驾车，处10日以下拘留，并处1000-2000元罚款，吊销机动车驾驶证。谨记：开车不喝酒，喝酒不开车。"},{"id":73,"type":"单选题","question":"上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？","options":["未悬挂机动车号牌","未携带身份证","未携带保险合同","未放置城市环保标志"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"未悬挂机动车号牌上路行驶，交警会扣留机动车，驾驶证记9分。"},{"id":74,"type":"判断题","question":"对使用其他车辆号牌、行驶证的车辆，交通警察可依法予以扣留。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"凡是使用其他车辆证件（登记证书，行驶证）、号牌、标志（检验合格、保险）的，交警都可依法扣留车辆，并处2000-5000元罚款。"},{"id":75,"type":"单选题","question":"年满20周岁的，不可以初次申请下列哪种准驾车型？","options":["大型货车","小型汽车","城市公交车","大型客车"],"answer":[3],"image":null,"tip":"","explanation":"注意审题，要同时满足两个条件。一是满20周岁，二是不可以初次申领。"},{"id":76,"type":"单选题","question":"机动车驾驶人请他人代为接受交通违法行为处罚和记分并支付经济利益的，由公安机关交通管理部门处所支付经济利益多少倍以下罚款，但最高不超过多少万元？","options":["三，五","三，三","两，五","两，两"],"answer":[0],"image":null,"tip":"","explanation":"请他人代为接受扣分并支付经济利益的，会被处以三倍以下罚款，不超五万。"},{"id":77,"type":"判断题","question":"驾驶校车、公路客运汽车、旅游客运汽车以外的其他载客汽车载人超过核定人数百分之百以上的，一次记12分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"小车超载百分百，扣12分。"},{"id":78,"type":"单选题","question":"初次申领机动车驾驶证的，可以申请下列哪种准驾车型？","options":["中型客车","大型客车","普通三轮摩托车","重型牵引挂车"],"answer":[2],"image":null,"tip":"","explanation":"初次申领驾驶证，不可申请大型客车、牵引车和中型客车准驾车型，选项中只有普通三轮摩托车是允许初次申请的。"},{"id":79,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["前雾灯打开","后雾灯打开","前照灯近光打开","前照灯远光打开"],"answer":[1],"image":"img/q079.jpg","tip":"","explanation":"看图中仪表板上的灯，有纵向线且为黄色光线向右，是后雾灯。"},{"id":80,"type":"单选题","question":"交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪？","options":["未报警","酒后、吸食毒品后驾驶机动车辆的","未带驾驶证","未抢救受伤人员"],"answer":[1],"image":null,"tip":"","explanation":"1.酒驾或毒驾；2.无驾驶资格驾车；3.车辆有安全隐患；4.无牌车或报废车；5.严重超载；6.肇事逃逸。具有以上任意一种行为，且致人重伤，负全部或主要责任的，都是交通肇事罪。"},{"id":81,"type":"单选题","question":"以下安全带系法正确的是？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[0],"image":"img/q081.jpg","tip":"","explanation":"安全带正确系法：肩部安全带斜着从胸前通过，不要放在胳膊下；腰部安全带系在髋部，不要系在腹部，所以图A是正确的。"},{"id":82,"type":"单选题","question":"交通违法行为累积记分未满多少分的，可以处理其驾驶的其他机动车的交通违法行为记录？","options":["24分","12分","9分","6分"],"answer":[1],"image":null,"tip":"","explanation":"一个记分周期记分未满12分，可以处理其驾驶的其他车辆的违法记录。"},{"id":83,"type":"单选题","question":"下列交通违法行为，一次记1分的是什么？","options":["驾驶载货汽车载物超过最大允许总质量百分之五十以上的","驾驶机动车在道路上行驶时，机动车驾驶人未按规定系安全带的","驾驶与准驾车型不符的机动车的","驾驶机动车不按交通信号灯指示通行的"],"answer":[1],"image":null,"tip":"","explanation":"驾驶机动车在道路上行驶时，机动车驾驶人未按规定系安全带的，一次记1分。"},{"id":84,"type":"单选题","question":"已注册登记的小型载客汽车有下列哪种情形，所有人不需要办理变更登记？","options":["机动车更换发动机","加装前后防撞装置","改变车身颜色","更换车身或者车架"],"answer":[1],"image":null,"tip":"机动车加装前后防撞装置，是为了更安全，对车辆本质无影响，无需变更登记。所以选“加装前后防撞装置”。","explanation":"更换发动机、改变车身颜色及更换车身和车架，都使车辆的本质发生变化，与行驶证上登记的信息不符，要申请变更登记。"},{"id":85,"type":"单选题","question":"机动车驾驶人补领机动车驾驶证后，使用原机动车驾驶证驾驶的，除由公安机关交通管理部门收回原机动车驾驶证外，还应当受到何种处罚？","options":["吊销驾驶证","拘留驾驶人","警告","罚款"],"answer":[3],"image":null,"tip":"驾驶证补领换新，不要再用旧的了，如果再用就要罚款。","explanation":"驾驶证补领后，原驾驶证作废，继续使用的收回原证再罚款20-200元。"},{"id":86,"type":"判断题","question":"驾驶机动车在道路上发生交通事故，任何情况下都应标明现场位置后，先行撤离现场。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“先行”就选对。（例外情况3题：当见到“先行撤离”或“会车”时选错）","explanation":"发生交通事故，只有无伤亡，无争议时，才可先行撤离现场再协商解决。题干说“任何情况”，是错的。"},{"id":87,"type":"判断题","question":"两辆机动车发生轻微碰擦事故后，为保证理赔，必须等保险公司人员到场鉴定后才能撤离现场。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“轻”就选对。（例外情况2题：当出现“不需”或“必须”时选错）","explanation":"轻微事故双方责任明确的，可先拍照撤离现场再协商解决，以免造成交通拥堵。"},{"id":88,"type":"单选题","question":"学习驾驶证明的有效期是多久？","options":["1年","2年","3年","4年"],"answer":[2],"image":null,"tip":"科二、科三各5次，有效期3年。","explanation":"学习驾驶证明有效期3年，从科目一考试合格后开始算起。"},{"id":89,"type":"单选题","question":"机动车驾驶人造成事故后逃逸构成犯罪的，吊销驾驶证且多长时间不得重新取得驾驶证？","options":["5年内","10年内","终生","20年内"],"answer":[2],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"凡是逃逸的，“终生”不得重新申领驾驶证。"},{"id":90,"type":"单选题","question":"驾驶人违反交通运输管理法规发生重大事故使公私财产遭受重大损失，可能会受到什么刑罚？","options":["处5年以上徒刑","处3年以下徒刑或者拘役","处3年以上徒刑","处3年以上7年以下徒刑"],"answer":[1],"image":null,"tip":"看文字答题，选项中见到“拘役”可直接选。","explanation":"重点看是否有逃逸，且是否因逃逸致人死亡。未逃逸：3年以下；逃逸或情节特别恶劣：3-7年；因逃逸致人死亡：7年以上。"},{"id":91,"type":"单选题","question":"对驾驶已达到报废标准的机动车上路行驶的驾驶人，会受到下列哪种处罚？","options":["处15日以下拘留","吊销机动车驾驶证","处20元以上200元以下罚款","追究刑事责任"],"answer":[1],"image":null,"tip":"驾驶拼装、报废车上路，罚款两百至两千，并处吊销驾照，所以选“吊销驾驶证”。","explanation":"驾驶报废车上路有安全隐患，将罚款200-2000元，吊销驾驶证，收缴车辆并强制报废。"},{"id":92,"type":"单选题","question":"机动车驾驶证被依法扣押、扣留、暂扣期间能否申请补发？","options":["可以申请","扣留期间可以临时申请","暂扣期间可以临时申请","不得申请补发"],"answer":[3],"image":null,"tip":"丢了才要补，扣押的还会还。所以选“不得申请补发”。","explanation":"驾驶证被扣说明有违法行为，当然不得申请补发。"},{"id":93,"type":"判断题","question":"小型载客汽车驾驶人在一个记分周期内参加满分教育的次数每增加一次或者累积记分每增加12分，道路交通安全法律、法规和相关知识的学习时间增加七天，每次满分学习的天数最多六十天。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"满分学习的次数每增加一次，学习时间增加7天，不超过60天。"},{"id":94,"type":"单选题","question":"轻型牵引挂车对应的车型代号是什么？","options":["C1","C2","C5","C6"],"answer":[3],"image":null,"tip":"","explanation":"C6代表轻型牵引挂车。"},{"id":95,"type":"判断题","question":"灯光开关在该位置时，前雾灯点亮。","options":["正确","错误"],"answer":[1],"image":"img/q095.jpg","tip":"","explanation":"波浪形状的光线在左是前雾灯，在右是后雾灯。看图中操纵杆上白色标线指向的是后雾灯。"},{"id":96,"type":"判断题","question":"组织他人代替实际机动车驾驶人参加审验教育的，没有违法所得的，由公安机关交通管理部门处二万元以下罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"组织他人代替参加审验，没有违法所得处二万元以下罚款。"},{"id":97,"type":"判断题","question":"驾驶证丢失后，驾驶人可以继续驾驶机动车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"没有驾驶证就不能驾驶车辆。"},{"id":98,"type":"单选题","question":"驾驶人户籍迁出原车辆管理所需要向什么地方的车辆管理所提出申请？","options":["迁出地","居住地","所在地","迁入地"],"answer":[3],"image":null,"tip":"","explanation":"南漂、北漂的福音，户籍迁出的可向迁入地车辆管理所申请换证。"},{"id":99,"type":"单选题","question":"公安机关交通管理部门对累积记分达到规定分值的驾驶人怎样处理？","options":["依法追究刑事责任","处15日以下拘留","终生禁驾","进行法律法规教育，重新考试"],"answer":[3],"image":null,"tip":"","explanation":"一个记分周期内记分达到12分的，扣留驾驶证，参加满分学习、考试。"},{"id":100,"type":"判断题","question":"机动车驾驶证在实习期内，驾驶人可以通过接受交通安全教育扣减交通违法行为记分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"在实习期内，申请接受交通安全教育扣减交通违法行为记分的，公安机关交通管理部门不予受理。"},{"id":101,"type":"单选题","question":"驾驶校车、公路客运汽车、旅游客运汽车载人超过核定人数未达到百分之二十的，一次记几分？","options":["3分","6分","9分","12分"],"answer":[1],"image":null,"tip":"","explanation":"驾驶校车、公路客运汽车、旅游客运汽车载人超过核定人数未达到百分之二十的，一次记6分。"},{"id":102,"type":"单选题","question":"交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪？","options":["未抢救受伤人员","未报警","未带驾驶证","为逃避法律追究逃离事故现场的"],"answer":[3],"image":null,"tip":"","explanation":"1.酒驾或毒驾；2.无驾驶资格驾车；3.车辆有安全隐患；4.无牌车或报废车；5.严重超载；6.肇事逃逸。具有以上任意一种行为，且致人重伤，负全部或主要责任的，都是交通肇事罪。"},{"id":103,"type":"判断题","question":"申请人在机动车驾驶人考试过程中组织作弊的，构成犯罪的，处三年以下有期徒刑或者拘役，并处或者单处罚金。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在考试中组织作弊的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"},{"id":104,"type":"判断题","question":"机动车被监察机关、人民法院、人民检察院、行政执法部门依法查封、扣押的，不予办理注册登记。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"机动车被查封、扣押期间不得办理注册登记。"},{"id":105,"type":"判断题","question":"机动车驾驶人可以在机动车驾驶证核发地或者交通违法行为发生地、处理地参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识学习，并在学习地参加考试。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"驾驶人可以在任意地参与法规学习，并在学习地参加考试。"},{"id":106,"type":"单选题","question":"准驾车型为小型自动挡汽车的，可以驾驶以下哪种车型？","options":["低速载货汽车","小型汽车","二轮摩托车","轻型自动挡载货汽车"],"answer":[3],"image":null,"tip":"C1准驾2/3/4，C2可驾自动挡，年满18就能考。","explanation":"小型自动挡汽车C2，只能驾驶C2相关车型，选项中只有轻型自动挡载货汽车属于C2；其他三项低速载货汽车是C3，小型汽车是C1，二轮摩托车是E，都不能驾驶。"},{"id":107,"type":"单选题","question":"持小型汽车驾驶证的驾驶人在下列哪种情况下需要接受审验？","options":["有效期满换发驾驶证时","一个记分周期末","记分周期未满分","记分周期满12分"],"answer":[0],"image":null,"tip":"期满换证时，公安机关交通管理部门要进行审验。","explanation":"驾驶证有效期满换证时，公安机关交通管理部门要进行审验。包括6年换发10年，10年换发长期。"},{"id":108,"type":"单选题","question":"机动车驾驶人有以下哪种违法行为的，暂扣六个月机动车驾驶证？","options":["醉酒后驾驶机动车的","伪造、变造机动车驾驶证的","饮酒后驾驶机动车的","使用伪造、变造机动车驾驶证的"],"answer":[2],"image":null,"tip":"酒驾暂扣6个月，再次酒驾就吊销、禁止申领AB照。","explanation":"注意“饮酒后”和“醉酒后”的区别。饮酒后驾车暂扣六个月驾驶证，醉酒后驾车直接吊销驾驶证。"},{"id":109,"type":"单选题","question":"饮酒后或者醉酒驾驶机动车发生重大交通事故构成犯罪的，依法追究刑事责任，吊销机动车驾驶证，将多少年内不得申请机动车驾驶证？","options":["五年","十年","二十年","终生"],"answer":[3],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"饮酒或醉酒驾车发生交通事故，构成犯罪的，吊销驾驶证终生不得重新申请。"},{"id":110,"type":"判断题","question":"驾驶机动车在道路上发生交通事故要立即将车移到路边。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“立即”就选错。（例外情况9题：当出现“报警”、“冷水”时选对）","explanation":"发生交通事故要立即停车，保护现场，如无人员伤亡且无争议的，可先撤离现场再协商解决。"},{"id":111,"type":"单选题","question":"在实习期内驾驶机动车的，应当在车身后部粘贴或者悬挂哪种标志？","options":["注意新手标志","注意避让标志","统一式样的实习标志","注意车距标志"],"answer":[2],"image":null,"tip":"实习期当然挂实习标志，所以选“统一式样的实习标志”。","explanation":"初次申领驾驶证实习期是一年，12个月，还需在车身后部粘贴或者悬挂统一式样的实习标志。"},{"id":112,"type":"判断题","question":"驾驶人因服兵役、出国（境）等原因延期审验期间不得驾驶机动车。","options":["正确","错误"],"answer":[0],"image":null,"tip":"兵役、出国无法审验，延期3年，期间禁驾。","explanation":"因服兵役、出国（境）申请延期审验的，延期期间不得驾驶机动车。"},{"id":113,"type":"单选题","question":"驾驶报废机动车上路行驶的驾驶人，除按规定罚款外，还要受到哪种处理？","options":["撤销驾驶许可","收缴驾驶证","强制恢复车况","吊销驾驶证"],"answer":[3],"image":null,"tip":"驾驶拼装、报废车上路，罚款两百至两千，并处吊销驾照，所以选“吊销驾驶证”。","explanation":"驾驶报废车上路有安全隐患，将罚款200-2000元，吊销驾驶证，收缴车辆并强制报废。"},{"id":114,"type":"判断题","question":"车辆发生轻微剐蹭事故，双方驾驶人争执不下，坚持在原地等待警察来处理，造成路面堵塞，该行为会受到罚款的处罚。","options":["正确","错误"],"answer":[0],"image":null,"tip":"该撤不撤，责令撤离罚200。","explanation":"发生轻微事故且无伤亡，应当自行撤离而未撤离，造成交通堵塞的，交警可依法处200元罚款，如有其他违法行为的，将一并处罚。"},{"id":115,"type":"判断题","question":"驾驶人违反交通运输管理法规发生重大事故使公私财产遭受重大损失的可能处3年以下徒刑或拘役。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"重点看是否有逃逸，且是否因逃逸致人死亡。未逃逸：3年以下；逃逸或情节特别恶劣：3-7年；因逃逸致人死亡：7年以上。"},{"id":116,"type":"单选题","question":"驾驶人未携带哪种证件驾驶机动车上路，交通警察可依法扣留车辆？","options":["机动车通行证","居民身份证","从业资格证","机动车行驶证"],"answer":[3],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"驾驶机动车应随车携带机动车行驶证、驾驶证，无论是电子版，还是纸质版，都需要随车携带。"},{"id":117,"type":"判断题","question":"驾驶拼装的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废，并吊销机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"拼装、报废车上路，吊驾照罚款，200至2000。","explanation":"驾驶拼装车上路有安全隐患，将罚款200-2000元，吊销驾驶证，收缴车辆并强制报废。"},{"id":118,"type":"判断题","question":"对未取得驾驶证驾驶机动车的，追究其法律责任。","options":["正确","错误"],"answer":[0],"image":null,"tip":"无证禁止驾车，违反依法追责。","explanation":"未取得驾驶证驾驶机动车，属于“无证驾驶”，将依法追究法律责任。"},{"id":119,"type":"单选题","question":"机动车驾驶人在参加接受交通安全教育扣减交通违法行为记分中弄虚作假的，由公安机关交通管理部门撤销相应记分扣减记录，恢复相应记分，处多少元以下罚款？","options":["一千","五百","两千","三千"],"answer":[0],"image":null,"tip":"","explanation":"参加交通安全教育扣减记分时，弄虚作假的，会被撤销记录，并处一千元以下罚款。"},{"id":120,"type":"单选题","question":"下列交通违法行为，一次记12分的是什么？","options":["驾驶机动车行经人行横道不按规定减速、停车、避让行人的","驾驶机动车在高速公路上违法停车的","驾驶机动车在城市快速路上违法占用应急车道行驶的","驾驶机动车在高速公路上倒车的"],"answer":[3],"image":null,"tip":"","explanation":"驾驶机动车在高速公路上倒车的，一次记12分"},{"id":121,"type":"单选题","question":"申请轻型牵引挂车准驾车型的，年龄不得超过多少周岁？","options":["70周岁","60周岁","65周岁","55周岁"],"answer":[1],"image":null,"tip":"","explanation":"轻型牵引挂车即C6，申请年龄限于20-60。"},{"id":122,"type":"判断题","question":"醉酒驾驶营运机动车依法被吊销机动车驾驶证未满十年的，不得申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"醉酒驾驶营运机动车，吊销机动车驾驶证，十年内不得重新取得机动车驾驶证。"},{"id":123,"type":"判断题","question":"机动车驾驶人参加满分教育现场学习、网络学习的天数累计不得少于五天，其中，现场学习的天数不得少于一天。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"满分学习现场和网络学习累积不少于五天，现场不少于二天。"},{"id":124,"type":"判断题","question":"小型载客汽车驾驶人在一个记分周期内累积记分满12分的，应当参加为期七天的道路交通安全法律、法规和相关知识学习。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"扣满12分，要参加7天的学习。"},{"id":125,"type":"单选题","question":"公安交通管理部门对驾驶人的交通违法行为除依法给予行政处罚外，实行下列哪种制度？","options":["违法登记制度","奖励里程制度","累积记分制度","强制报废制度"],"answer":[2],"image":null,"tip":"","explanation":"驾驶人有交通违法行为，除依法给予行政处罚外，实行累积记分制度。"},{"id":126,"type":"单选题","question":"如图所示，遇到这种情况的路口，以下做法正确的是什么？","options":["沿左侧车道掉头","该路口不能掉头","选择中间车道掉头","在路口内掉头"],"answer":[1],"image":"img/q126.jpg","tip":"","explanation":"注意左侧标志：红圈白底红杠+掉头箭头=禁止掉头标志，表示该路口禁止掉头。"},{"id":127,"type":"单选题","question":"车辆使用远光灯，下列哪个指示灯会亮？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[3],"image":"img/q127.jpg","tip":"","explanation":"题干问远光灯，图中找光线在左且为平行线的，即图D。注意看清选项和图片编号的对应关系。"},{"id":128,"type":"单选题","question":"C6车型代号对应的准驾车型是什么？","options":["轻型牵引挂车","重型牵引挂车","小型自动挡汽车","中型客车"],"answer":[0],"image":null,"tip":"","explanation":"为促进房车旅游新业态发展，新增轻型牵引挂车准驾车型（C6）。"},{"id":129,"type":"单选题","question":"中型客车对应的车型代号是什么？","options":["A2","B1","B2","A1"],"answer":[1],"image":null,"tip":"","explanation":"注意区分B1和B2，B1表示是的中型客车。"},{"id":130,"type":"判断题","question":"参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识现场学习满一小时且考试合格的，一次扣减12分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"参加满分学习现场学习时，满1小时且考试合格，一次减2分。"},{"id":131,"type":"判断题","question":"在道路上车辆发生故障、事故停车后，不按规定使用灯光或者设置警告标志的，一次记1分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"不按规定设置警告标志，一次记3分，不是1分。"},{"id":132,"type":"单选题","question":"下列交通违法行为，一次记12分的是什么？","options":["驾驶货车运载爆炸物品，未按指定的时间、路线行驶的","代替实际机动车驾驶人接受交通违法行为处罚和记分牟取经济利益的","驾驶小型客车在高速公路上行驶超过规定时速百分之二十以上未达到百分之五十的","驾驶机动车运载超限的不可解体的物品，未按指定时间、路线行驶的"],"answer":[1],"image":null,"tip":"","explanation":"代替实际机动车驾驶人接受交通违法行为处罚和记分牟取经济利益的，一次记12分。"},{"id":133,"type":"判断题","question":"申请人隐瞒有关情况或者提供虚假材料申请校车驾驶资格的，公安机关交通管理部门不予受理或者不予办理，处五百元以下罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"提供虚假资料申请校车资格的，处500元以下罚款。"},{"id":134,"type":"判断题","question":"改变车身颜色、更换发动机、车身或者车架，未按照规定的时限办理变更登记的，由公安机关交通管理部门处警告或者二百元以下罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"改变车身颜色、更换发动机、车身或者车架，未按规定时限办理变更登记的，由公安机关交通管理部门处警告或者二百元以下罚款。"},{"id":135,"type":"判断题","question":"代替他人或者让他人代替自己参加机动车驾驶人考试，构成犯罪的，处拘役或者管制，并处或者单处罚金。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"代替他人或者让他人代替自己参加考试的，处拘役或者管制，并处或者单处罚金。"},{"id":136,"type":"单选题","question":"以下哪个指示灯亮时，提醒驾驶人安全带插头未插入锁扣？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[0],"image":"img/q136.jpg","tip":"","explanation":"题干问安全带未插入，图中找有安全带的标志，即图A。其他三项图B是水温指示灯，图C是ABS指示灯，图D是燃油指示灯。要注意选项与图片编号的对应关系。"},{"id":137,"type":"判断题","question":"申请人以欺骗、贿赂等不正当手段取得校车驾驶资格的，处两千元以下罚款，申请人在三年内不得再次申请校车驾驶资格。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"用欺骗、贿赂等不正当手段获得校车驾驶资格，罚款两千以下，三年内不得再次申领。"},{"id":138,"type":"单选题","question":"驾驶人在驾驶证有效期满前多长时间申请换证？","options":["30日内","60日内","90日内","6个月内"],"answer":[2],"image":null,"tip":"信息发生变化是30天，有效期满是90天。","explanation":"驾驶证过期立马作废，要在有效期满前90日内申请换证。"},{"id":139,"type":"单选题","question":"初次申领的机动车驾驶证的有效期为多少年？","options":["3年","5年","6年","12年"],"answer":[2],"image":null,"tip":"初领6年，无满分记录可换发10年、长期。","explanation":"驾驶证有效期分为六年、十年和长期，初次申领是六年。"},{"id":140,"type":"单选题","question":"隐瞒有关情况或者提供虚假材料申请机动车驾驶证，申请人在多少年内不得再次申领机动车驾驶证？","options":["1年","2年","3年","4年"],"answer":[0],"image":null,"tip":"","explanation":"凡是有“虚假”行为的，一年内不得再次申请驾驶证。（假一吊二撤三醉五逃终生）"},{"id":141,"type":"判断题","question":"驾驶机动车发生财产损失交通事故，当事人对事实及成因无争议的可先撤离现场。","options":["正确","错误"],"answer":[0],"image":null,"tip":"财产损失事故，协商无争议，拍好照片，快点撤离，避免拥堵。","explanation":"发生交通事故，无伤亡、无争议的，可先撤离再协商解决。如未及时撤离现场，造成交通堵塞的，交警可依法对驾驶人处以200元罚款。"},{"id":142,"type":"判断题","question":"驾驶机动车与行人之间发生交通事故造成人身伤亡、财产损失的，机动车一方没有过错的，不承担赔偿责任。","options":["正确","错误"],"answer":[1],"image":null,"tip":"判责：非故意都负责；故意、不礼让的负全责；掉货物的负全责。","explanation":"机动车与行人发生事故，机动车一方无过错的，承担不超过10%的赔偿责任。"},{"id":143,"type":"判断题","question":"驾驶机动车在道路上发生交通事故，当事人不能自行移动车辆的，应当保护现场并立即报警。","options":["正确","错误"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"既然不能自行移动车辆，那就要保护现场并立即报警，请交警协助处理。"},{"id":144,"type":"判断题","question":"驾驶机动车碰撞建筑物、公共设施后可即行撤离现场。","options":["正确","错误"],"answer":[1],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"碰撞建筑物、公共设施的，要保护现场并立即报警等待处理，不得驶离。即行撤离现场会按肇事逃逸处理。"},{"id":145,"type":"判断题","question":"驾驶机动车载货长度、宽度、高度超过规定的，一次记1分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"货车长宽高超限扣1分。","explanation":"载货长度、宽度、高度超过规定的，一次记1分。"},{"id":146,"type":"判断题","question":"驾驶人在发生交通事故后因抢救伤员变动现场时要标明位置。","options":["正确","错误"],"answer":[0],"image":null,"tip":"路遇事故，抢救报警，标明位置。","explanation":"因抢救受伤人员变动现场的，应当标明位置，以备责任判定及案情所用。"},{"id":147,"type":"判断题","question":"驾驶人有使用其他车辆检验合格标志嫌疑的，交通警察可依法扣留车辆。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"凡是使用其他车辆证件（登记证书，行驶证）、号牌、标志（检验合格、保险）嫌疑的，交警会依法扣留车辆。"},{"id":148,"type":"单选题","question":"驾驶人在下列哪种情况下不能驾驶机动车？","options":["饮酒后","喝茶后","喝咖啡后","喝牛奶后"],"answer":[0],"image":null,"tip":"车有隐患，人不清醒，禁止上路。","explanation":"饮酒后驾驶机动车上路是违法行为，暂扣六个月驾驶证，并处罚款。"},{"id":149,"type":"判断题","question":"驾驶机动车发生未造成人身伤亡的交通事故后，当事人对事实及成因有争议的，应当立即报警。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"对于事故成因不明的交通事故，应及时报警。"},{"id":150,"type":"判断题","question":"上路行驶的机动车未放置检验合格标志的，交通警察可依法扣留机动车。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"没有检验合格标志，会被扣留车辆。"},{"id":151,"type":"判断题","question":"驾驶机动车在高速公路或者城市快速路上不按规定车道行驶的，一次记3分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在高速公路或者城市快速路上不按规定车道行驶的，一次记3分。"},{"id":152,"type":"判断题","question":"驾驶机动车不得有拨打接听手持电话、观看电视等妨碍安全驾驶的行为。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"拨打接听手持电话、观看电视会导致分心。"},{"id":153,"type":"判断题","question":"机动车驾驶人在一个记分周期内二次累积记分满12分，应当在道路交通安全法律、法规和相关知识考试合格后，按规定预约参加道路驾驶技能考试。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"一个记分周期内二次累积记分满12分，应在满分学习考试合格后，按规定预约道路驾驶技能考试。"},{"id":154,"type":"单选题","question":"机动车仪表板上如图所示指示灯一直亮表示什么？","options":["防抱死制动系统故障","安全气囊处于故障状态","安全气囊处于工作状态","安全带没有系好"],"answer":[1],"image":"img/q154.jpg","tip":"","explanation":"图中仪表板上黄色圆球表示安全气囊，只有当安全气囊处于故障状态才会一直亮起。"},{"id":155,"type":"单选题","question":"驾驶机动车在高速公路或者城市快速路上不按规定车道行驶的，一次记几分？","options":["1分","9分","3分","6分"],"answer":[2],"image":null,"tip":"","explanation":"在高速公路或城市快速路不按规定车道行驶，一次记3分。"},{"id":156,"type":"单选题","question":"下列交通违法行为，一次记9分的是什么？","options":["驾驶7座以上载客汽车载人超过核定人数百分之五十以上未达到百分之百的","驾驶校车载人超过核定人数百分之二十以上的","代替实际机动车驾驶人接受交通违法行为处罚和记分牟取经济利益的","使用伪造、变造的机动车号牌或者使用其他机动车号牌的"],"answer":[0],"image":null,"tip":"","explanation":"驾驶7座以上载客汽车载人超过核定人数百分之五十以上未达到百分之百的，一次记9分。"},{"id":157,"type":"判断题","question":"交通事故造成人员重伤但驾驶人愿意承担全部责任的，可以自行协商处理。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"造成重伤，就属于比较严重的交通事故，公安机关必须介入调查，因此不可以自行解决。"},{"id":158,"type":"判断题","question":"年龄在50周岁以上的机动车驾驶人，应当每年进行一次身体检查，并向公安机关交通管理部门申报身体条件情况。","options":["正确","错误"],"answer":[1],"image":null,"tip":"70岁以上，每年体检排隐患，一年不交会注销。","explanation":"70周岁以上的驾驶人，要每年进行身体检查，提交身体证明。题干说“50周岁”是错的。"},{"id":159,"type":"判断题","question":"将转向灯开关向上提，左转向灯亮。","options":["正确","错误"],"answer":[1],"image":"img/q159.jpg","tip":"转向灯开关：下左上右。","explanation":"图中是灯光、信号组合开关，提拉这个开关可以开启左右转向灯。向上提右转向灯亮，向下拉左转向灯亮。"},{"id":160,"type":"单选题","question":"驾驶这种机动车上路行驶属于什么行为？","options":["违规行为","违章行为","违法行为","犯罪行为"],"answer":[2],"image":"img/q160.jpg","tip":"扣分的都是违法行为，影响驾驶的是陋习。","explanation":"图中机动车故意遮挡号牌，违反《道路交通安全法》，是违法行为。"},{"id":161,"type":"判断题","question":"申请人患有精神病的，可以申领机动车驾驶证，但是在发病期间不得驾驶机动车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"疾病影响驾驶，禁止申领驾照。","explanation":"只要患有精神病，就不得申请机动车驾驶证。"},{"id":162,"type":"判断题","question":"驾驶人的驾驶证损毁后不得驾驶机动车。","options":["正确","错误"],"answer":[0],"image":null,"tip":"无证禁止驾车，违反依法追责。","explanation":"驾驶证损毁后信息无法辨认，不得驾驶机动车，需申请补发。"},{"id":163,"type":"判断题","question":"机动车行驶证灭失、丢失，机动车所有人要向登记地车辆管理所申请补领、换领。","options":["正确","错误"],"answer":[0],"image":null,"tip":"机动车相关证件，补、换、备案都找登记地。","explanation":"机动车行驶证灭失、丢失的，要向登记地车辆管理所申请补领、换领。注意机动车相关的补领和换领，都找登记地。"},{"id":164,"type":"判断题","question":"持有小型汽车驾驶证的驾驶人，发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验，同时应当申报身体条件情况。","options":["正确","错误"],"answer":[0],"image":null,"tip":"致人重伤或死亡，周期结束30日内审，禁止增驾AB照。","explanation":"驾驶人发生交通事故造成人员死亡，但未吊销驾驶证的，要在记分周期后30日内接受审验。"},{"id":165,"type":"判断题","question":"安装防抱死制动装置（ABS）的机动车制动时，制动距离会大大缩短，因此不必保持安全车距。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“ABS”就选对。（例外情况2题：当出现“短”时选错）","explanation":"不要依赖ABS缩短制动距离，特别是在冰雪路面上紧急制动时，ABS无法有效的缩短制动距离。行车时一定要保持足够的安全距离，题干说“不必”是错的。"},{"id":166,"type":"判断题","question":"对违法驾驶发生重大交通事故且构成犯罪的，不追究其刑事责任。","options":["正确","错误"],"answer":[1],"image":null,"tip":"构成犯罪，追究刑事责任。","explanation":"重大事故且构成犯罪的，都将依法追究刑事责任。"},{"id":167,"type":"判断题","question":"初次申领的机动车驾驶证的有效期为6年。","options":["正确","错误"],"answer":[0],"image":null,"tip":"初领6年，无满分记录可换发10年、长期。","explanation":"驾驶证有效期分为六年、十年和长期，初次申领是六年。"},{"id":168,"type":"判断题","question":"驾驶人在机动车驾驶证的6年有效期内，每个记分周期均未达到12分的，换发长期有效的机动车驾驶证。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"6年换10年，10年换长期。"},{"id":169,"type":"判断题","question":"机动车驾驶人有二起以上交通违法行为应当予以记分的，记分分值不累积计算。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"有二起以上违法记分，分值累积计算。"},{"id":170,"type":"判断题","question":"驾驶机动车不按交通信号灯指示通行的，一次记3分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"不按交通信号灯指示通行的，一次记6分。"},{"id":171,"type":"判断题","question":"申请人在考试过程中有贿赂、舞弊行为的，已经通过考试的其他科目成绩无效，处二千元以下罚款，申请人在一年内不得再次申领机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"贿赂、舞弊行为，取消考试资格，成绩无效，罚款2000以下，1年内不得再次申领。"},{"id":172,"type":"判断题","question":"小型汽车驾驶人发生交通事故造成人员死亡，承担同等以上责任未被吊销驾驶证的，应当在记分周期结束后90日内接受审验。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"造成人员死亡承担同等以上责任，驾驶证未被吊销，该记分周期结束30日内接受审验。"},{"id":173,"type":"判断题","question":"组织他人参加审验教育时在签注学习记录、学习过程中弄虚作假的，有违法所得的，由公安机关交通管理部门处违法所得三倍以下罚款，但最高不超过二万元。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"组织他人参加审验教育时在签注学习记录、学习过程中弄虚作假有违法所得的，处违法所得三倍以下罚款，但最高不超过二万元。"},{"id":174,"type":"判断题","question":"造成致人轻伤以上或者死亡的交通事故后逃逸，尚不构成犯罪的，一次记9分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"造成致人轻伤以上或者死亡的交通事故后逃逸，尚不构成犯罪的一次记12分。"},{"id":175,"type":"判断题","question":"机动车驾驶人使用伪造、变造的行驶证的，一次记9分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的，一次记12分。"},{"id":176,"type":"单选题","question":"机动车登记证书、行驶证灭失、丢失或者损毁的，机动车所有人应当向哪个部门申请补领、换领？","options":["住地交警支队车辆管理所","驾驶证核发地车辆管理所","登记地车辆管理所","当地公安局"],"answer":[2],"image":null,"tip":"","explanation":"只要是跟机动车相关的证件（登记证书、号牌、行驶证等）申请补发的，都在登记地车管所。"},{"id":177,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["充电电流过大","蓄电池损坏","电流表故障","充电电路故障"],"answer":[3],"image":"img/q177.jpg","tip":"","explanation":"图中仪表板上像个电池有加减号，是电瓶指示灯，一直亮起，说明充电电路故障。"},{"id":178,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["已开启前照灯近光","已开启前雾灯","已开启前照灯远光","已开启后雾灯"],"answer":[2],"image":"img/q178.jpg","tip":"","explanation":"看图中仪表板上的灯，光线为蓝色平行线，是远光灯。延展：光线是绿色倾斜线，是近光灯。"},{"id":179,"type":"判断题","question":"机动车仪表板上如图所示指示灯一直亮，表示安全气囊处于工作状态。","options":["正确","错误"],"answer":[1],"image":"img/q179.jpg","tip":"","explanation":"图中仪表板上黄色圆球表示安全气囊，只有当安全气囊处于故障状态才会一直亮起。题干说“工作状态”是错的。"},{"id":180,"type":"判断题","question":"机动车仪表板上如下图所示指示灯亮表示发动机可能机油量不足。","options":["正确","错误"],"answer":[0],"image":"img/q180.jpg","tip":"","explanation":"看图中仪表板上的灯像个在滴油的油壶，表示该车发动机机油压力过低或油量不足。"},{"id":181,"type":"单选题","question":"如下图所示这个符号的开关控制什么装置？","options":["后风窗玻璃除霜或除雾","前风窗玻璃刮水器及洗涤器","后风窗玻璃刮水器及洗涤器","前风窗玻璃除霜或除雾"],"answer":[1],"image":"img/q181.jpg","tip":"","explanation":"图中符号是扇形且带喷嘴，为前风窗玻璃刮水器及洗涤器。延展：方形是后窗刮水器及洗涤器。"},{"id":182,"type":"单选题","question":"机动车仪表板上如下图所示指示灯亮表示什么？","options":["空气内循环","地板及迎面出风","空气外循环","侧面及地板出风"],"answer":[1],"image":"img/q182.jpg","tip":"","explanation":"图中仪表板上箭头代表出风方向，一个朝向地面，一个朝向人脸，表示地板及迎面出风。"},{"id":183,"type":"判断题","question":"如图所示，这种情况下，只要后方、对向无来车，可以掉头。","options":["正确","错误"],"answer":[0],"image":"img/q183.jpg","tip":"","explanation":"图中路面标线是黄色虚线，且无禁止掉头标志，在不影响其他车辆正常行驶的情况下，可以掉头。"},{"id":184,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮时，提醒驾驶人安全带插头未插入锁扣。","options":["正确","错误"],"answer":[0],"image":"img/q184.jpg","tip":"","explanation":"看图中仪表板上是安全带指示灯，一直亮起，说明没系好安全带，也就是安全带插头未插入锁扣。"},{"id":185,"type":"单选题","question":"以下哪个指示灯亮时，表示发动机温度过高？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[1],"image":"img/q185.jpg","tip":"","explanation":"题干问发动机温度过高，图中找温度计，即图B。其他三项图A是机油指示灯，图C是ABS指示灯，图D是燃油指示灯。要注意选项与图片编号的对应关系。"},{"id":186,"type":"单选题","question":"关于机动车驾驶人参加审验教育时在签注学习记录、学习过程中弄虚作假的会受到的处罚，以下说法错误的是什么？","options":["处一千元以下罚款","相应学习记录无效","暂扣机动车驾驶证","重新参加审验学习"],"answer":[2],"image":null,"tip":"","explanation":"在参加审验教育时，驾驶证此时已经是被暂扣的状态，无需再次暂扣。"},{"id":187,"type":"判断题","question":"机动车所有权转让后，现机动车所有人未按照规定的时限办理转让登记的，由公安机关交通管理部门处警告或者一千元以下罚款。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"所有权转让后，现机动车所有人要及时申请转让登记，否则处警告或者二百元以下罚款。"},{"id":188,"type":"单选题","question":"关于申请增加轻型牵引挂车准驾车型的要求，以下说法正确的是什么？","options":["取得小型汽车、小型自动挡汽车驾驶证1年","本记分周期和最近连续三个记分周期内没有记满12分记录的","本记分周期和最近连续一个记分周期内有记满12分记录的，已参加满分教育且考试通过","取得小型自动挡汽车驾驶证3年以上"],"answer":[0],"image":null,"tip":"","explanation":"取得小型汽车、小型自动挡汽车驾驶证一年以上，才能申请增加轻型牵引挂车准驾车型。"},{"id":189,"type":"单选题","question":"在最近几个记分周期内，机动车驾驶人饮酒后驾驶机动车受到过处罚的，不得通过接受交通安全教育扣减交通违法行为记分？","options":["1个","2个","3个","4个"],"answer":[2],"image":null,"tip":"","explanation":"最近3个记分周期内，有饮酒驾驶机动车受到过处罚的，不得参加满分学习。"},{"id":190,"type":"判断题","question":"驾驶机动车载运爆炸物品，未悬挂警示标志并采取必要的安全措施的，一次记12分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"运载爆炸物品，未悬挂警示标志并采取必要安全措施，一次记6分。"},{"id":191,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮时，不影响正常行驶。","options":["正确","错误"],"answer":[1],"image":"img/q191.jpg","tip":"","explanation":"看图中仪表板上的灯，圆圈里有个“！”是制动系统出现异常标志，行车中亮此灯需要尽快维修。题干说“不影响”是错的。"},{"id":192,"type":"判断题","question":"组织、参与实施欺骗、贿赂等不正当手段取得机动车驾驶证牟取经济利益的，由公安机关交通管理部门处违法所得三倍以上五倍以下罚款，但最高不超过十万元。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"组织、参与实施不正常手段获得驾驶证，牟取经济利益的，处违法所得三倍以上五倍以下罚款，最高不超过十万元。"},{"id":193,"type":"判断题","question":"驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路、城市快速路上行驶超过规定时速百分之五十以上的，一次记9分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶上述机动车超过规定时速50%以上，一次记12分。"},{"id":194,"type":"单选题","question":"驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路上行驶超过规定时速百分之二十以上未达到百分之五十的，一次记几分？","options":["9分","3分","1分","6分"],"answer":[3],"image":null,"tip":"","explanation":"超过规定时速20%-50%之间，一次记6分。"},{"id":195,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮，提示发动机舱开启。","options":["正确","错误"],"answer":[1],"image":"img/q195.jpg","tip":"","explanation":"图中仪表板上黄色车辆明显后盖开启，一般车型是行李舱，提醒驾驶员要关好后再起步。题干说“发动机舱”是错的。"},{"id":196,"type":"判断题","question":"机动车驾驶人同时被处以暂扣机动车驾驶证的，经满分学习、考试合格且罚款已缴纳的，记分予以清除，无需等暂扣期限届满即可发还机动车驾驶证。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶证暂扣期间的，满分学习考试合格后，也要等到暂扣期限届满才会发还机动车驾驶证。"},{"id":197,"type":"判断题","question":"驾驶人在实习期内不可以单独驾驶机动车上高速公路行驶，在增加准驾车型后的实习期内，驾驶原准驾车型的机动车时不受上述限制。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"增驾车型实习期内，还是可以驾驶原来的准驾车型上高速。"},{"id":198,"type":"判断题","question":"饮酒后驾驶机动车的，一次记12分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"饮酒后驾驶机动车的，将被一次记12分。谨记：开车不喝酒，喝酒不开车！"},{"id":199,"type":"判断题","question":"机动车驾驶证遗失、损毁无法辨认时，机动车驾驶人应当向机动车驾驶证核发地或者核发地以外的车辆管理所申请补发。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"根据新规，驾驶证的补领、补发可以到全国任意车管所进行办理。"},{"id":200,"type":"判断题","question":"机动车驾驶人可以一次性处理完毕同一辆机动车的多起交通违法行为记录，记分分值累积计算。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"机动车驾驶人可以一次性处理同一辆机动车的多起交通违法行为记录，若未记满12分，还可以处理其他的车辆违法记录，若记满12分，则不能再处理其他机动车的违法记录。"},{"id":201,"type":"单选题","question":"以下哪个仪表表示水温表？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[2],"image":"img/q201.jpg","tip":"","explanation":"题干问水温表，图中找温度计，即图C。其他三项图A是转速表，图B是速度和里程表，图D是燃油表。要注意选项与图片编号的对应关系。"},{"id":202,"type":"判断题","question":"机动车所有人申请转移登记前，应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"申请转让登记前，要把该车所有的违法行为和事故处理完毕。"},{"id":203,"type":"判断题","question":"申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可，处二千元以下罚款，申请人在3年内不得再次申领机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可，处二千元以下罚款；申请人在三年内不得再次申领机动车驾驶证。"},{"id":204,"type":"判断题","question":"驾驶人违反交通运输管理法规发生重大事故后，逃逸或者有其他特别恶劣情节的，处7年以上有期徒刑。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"重点看是否有逃逸，且是否因逃逸致人死亡。未逃逸：3年以下；逃逸或情节特别恶劣：3-7年；因逃逸致人死亡：7年以上。"},{"id":205,"type":"判断题","question":"机动车仪表板上（如图所示）亮时，提醒发动机需要补充机油。","options":["正确","错误"],"answer":[1],"image":"img/q205.jpg","tip":"油箱亮起燃油少，温度计亮温度高。","explanation":"看图中仪表板上是燃油指示灯，车辆启动后一直亮起，说明油箱内燃油已到最低液面，要及时补充燃油。题干说“补充机油”是错的。"},{"id":206,"type":"单选题","question":"如图所示，A车若想左转，以下做法正确的是什么？","options":["直行通过，重新选择行驶路线","从直行车道左转","直接变更到左转车道","向右转弯，重新选择行驶路线"],"answer":[0],"image":"img/q206.jpg","tip":"看图答题，A车在直行车道上，想要左转弯，只能继续向前行驶，寻找合适的位置转弯。所以选“直行通过，重新选择行驶路线”。","explanation":"A车在直行车道，不得左转弯。只能继续前行，寻找合适位置转弯。"},{"id":207,"type":"判断题","question":"点火开关在LOCK位置拔出钥匙转向盘会锁住。","options":["正确","错误"],"answer":[0],"image":"img/q207.jpg","tip":"点火开关按顺时针：锁方向、部分通电、全车通电、起动机起动。","explanation":"点火开关分为四个挡位，LOCK-ACC-ON-START，图中指向LOCK，拔出钥匙后，会切断电源，锁定方向盘。"},{"id":208,"type":"判断题","question":"对有使用伪造或变造检验合格标志嫌疑的车辆，交通警察只进行罚款处罚。","options":["正确","错误"],"answer":[1],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"凡是有使用伪造、变造标志（检验合格、保险）嫌疑的，交警会依法扣留车辆。"},{"id":209,"type":"判断题","question":"记分满12分的驾驶人拒不参加学习和考试的将被公告驾驶证停止使用。","options":["正确","错误"],"answer":[0],"image":null,"tip":"满分学习并考试，拒不参加证停用。","explanation":"记分达到12分的，需要参加道路交通安全法律、法规学习，拒不参加的驾驶证将被公告停止使用。"},{"id":210,"type":"判断题","question":"小型手动挡汽车科目二考试内容包括倒车入库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯。","options":["正确","错误"],"answer":[0],"image":null,"tip":"科二必考内容：倒库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯。","explanation":"小型手动挡汽车C1科二必考：倒车入库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯。"},{"id":211,"type":"判断题","question":"驾驶机动车在道路上违反交通安全法规的行为属于违法行为。","options":["正确","错误"],"answer":[0],"image":null,"tip":"扣分的都是违法行为，影响驾驶的是陋习。","explanation":"违反法律法规属于“违法行为”，现已无违章和违规的说法。"},{"id":212,"type":"判断题","question":"拼装的机动车只要认为安全就可以上路行驶。","options":["正确","错误"],"answer":[1],"image":null,"tip":"车有隐患，人不清醒，禁止上路。","explanation":"拼装车未进行安全技术检测，有安全隐患，不能上路行驶。"},{"id":213,"type":"单选题","question":"这个仪表是何含义？","options":["电流表","压力表","水温表","燃油表"],"answer":[3],"image":"img/q213.jpg","tip":"km/h速度，r/min转速，温度计是水温，油箱是燃油。","explanation":"看图中仪表盘上有个加油机，是燃油表。"},{"id":214,"type":"单选题","question":"这个标志是何含义？","options":["左转车道","掉头车道","绕行车道","分向车道"],"answer":[1],"image":"img/q214.jpg","tip":"矩形蓝底、两侧虚线，有什么车型或箭头就是什么车道。","explanation":"图中正方形蓝底标志，两侧虚线中间有掉头箭头，是掉头车道标志，表示该车道的行驶方向是只准掉头。"},{"id":215,"type":"判断题","question":"发生交通事故造成人员受伤时，要保护现场并立即报警。","options":["正确","错误"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"造成人员受伤的，一定要保护现场并立即报警等待救援。"},{"id":216,"type":"判断题","question":"驾驶机动车在道路上违反道路通行规定应当接受相应的处罚。","options":["正确","错误"],"answer":[0],"image":null,"tip":"扣分的都是违法行为，影响驾驶的是陋习。","explanation":"违反规定就要接受相应的处罚。"},{"id":217,"type":"判断题","question":"不得驾驶具有安全隐患的机动车上道路行驶。","options":["正确","错误"],"answer":[0],"image":null,"tip":"车有隐患，人不清醒，禁止上路。","explanation":"安全驾驶最重要，有安全隐患的车坚决不能开。"},{"id":218,"type":"判断题","question":"对有伪造或变造号牌、行驶证嫌疑的车辆，交通警察可依法予以扣留。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"只要是伪造或变造的，就可依法扣留车辆。如伪造或变造的是号牌、行驶证等，还将处15日以下拘留，并处2000-5000元罚款，构成犯罪的，还将依法追究刑事责任。"},{"id":219,"type":"判断题","question":"驾驶机动车上路前应当检查车辆安全技术性能。","options":["正确","错误"],"answer":[0],"image":null,"tip":"上路检查车辆性能，消除隐患减伤害。","explanation":"驾驶人上路行驶前，要检查车辆安全性能，比如轮胎、制动，不开有安全隐患的车。"},{"id":220,"type":"判断题","question":"机动车行驶中，车上少年儿童可不使用安全带。","options":["正确","错误"],"answer":[1],"image":null,"tip":"门关好再起步，车停稳再开门，人员系安全带。","explanation":"所有乘车人都要系好安全带，少年儿童也不例外，另外还需要根据年龄配备适当的安全座椅加强保护。"},{"id":221,"type":"判断题","question":"已注册登记的机动车达到国家规定的强制报废标准的，应当向登记地车辆管理所申请注销登记。","options":["正确","错误"],"answer":[0],"image":null,"tip":"看文字答题，题干中见到“注销”就选对。（例外情况1题：当出现“不会被注销”时选错）","explanation":"凡是机动车相关的，都找登记地。达到报废标准的机动车，要到登记地车管所申请注销。"},{"id":222,"type":"判断题","question":"事故报警时，要向交警提供事故地点、人员伤情、车辆号牌等信息，协助交警快速定位到达现场。","options":["正确","错误"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"交通事故报警时，要把地点、伤情、车辆号牌等重要信息说清楚，以保证交警最快时间到达事故地点，处理事故。"},{"id":223,"type":"单选题","question":"同车道行驶的车辆前方遇到下列哪种车辆不得超车？","options":["大型客货车","执行任务的消防车","公共汽车","出租汽车"],"answer":[1],"image":null,"tip":"危险路段、对向有车、前车向左或不让、遇执行公务的特种车，不能超车。","explanation":"执行紧急任务的警车、消防车、救护车、工程救险车，正在争分夺秒地保障人民生命和财产安全，具有优先通行权，不可超越。"},{"id":224,"type":"单选题","question":"上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？","options":["未携带保险合同","未携带机动车登记证书","未放置城市环保标志","悬挂变造的机动车号牌"],"answer":[3],"image":null,"tip":"","explanation":"伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处二千元以上五千元以下罚款;构成犯罪的，依法追究刑事责任。"},{"id":225,"type":"判断题","question":"驾驶机动车在道路上行驶时，机动车驾驶人未按规定系安全带的，一次记1分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"未按规定系安全带的，一次记1分。"},{"id":226,"type":"判断题","question":"打开前雾灯开关，如下图所示指示灯亮起。","options":["正确","错误"],"answer":[0],"image":"img/q226.jpg","tip":"","explanation":"绿光在左是前雾灯，黄光在右是后雾灯。"},{"id":227,"type":"判断题","question":"如图所示，校车在最右侧车道停靠上下学生时，校车停靠车道后方和相邻机动车道的机动车应停车等待，最左侧车道上的机动车应当减速通过。","options":["正确","错误"],"answer":[0],"image":"img/q227.jpg","tip":"","explanation":"校车后方和相邻的要停车，其他车道可减速通过。"},{"id":228,"type":"判断题","question":"如图所示，驾驶机动车在这种情况下可以左转弯。","options":["正确","错误"],"answer":[0],"image":"img/q228.jpg","tip":"","explanation":"红灯停，绿灯行，绿灯亮的方向可以行驶。"},{"id":229,"type":"判断题","question":"三年内有吸食、注射毒品行为，不得申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"有吸毒、戒毒未满三年，或者毒瘾未戒的，都不得申请驾驶证。"},{"id":230,"type":"判断题","question":"驾驶机动车在高速公路上发生故障时，驾驶人应开启危险报警闪光灯增大警示范围。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"开双闪可以增大警示范围，提醒他人。"},{"id":231,"type":"判断题","question":"驾驶机动车不按规定会车，或者在高速公路、城市快速路以外的道路上不按规定倒车、掉头的，一次记1分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"不按规定会车，或者在高速公路、城市快速路以外的道路上不按规定倒车、掉头的，一次记1分。"},{"id":232,"type":"判断题","question":"机动车登记证书、行驶证灭失、丢失或者损毁的，机动车所有人应当向居住地车辆管理所申请补领、换领。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"只要是跟机动车相关的证件（登记证书、号牌、行驶证等）申请补发的，都在登记地车管所。"},{"id":233,"type":"单选题","question":"机动车仪表板上如下图所示指示灯亮表示什么？","options":["空气内循环","空气外循环","迎面吹风","风窗玻璃除霜"],"answer":[1],"image":"img/q233.jpg","tip":"","explanation":"图中仪表板上的箭头从车外指向车内是空气外循环；箭头只在车内转是空气内循环。"},{"id":234,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["危险报警闪光灯开启","前照灯开启","前后位置灯开启","前后雾灯开启"],"answer":[2],"image":"img/q234.jpg","tip":"","explanation":"看图中仪表板上的灯像个蝴蝶结，是前后位置灯。"},{"id":235,"type":"单选题","question":"行车中仪表板上如图所示指示灯亮表示什么？","options":["发动机温度过低","发动机温度过高","发动机冷却系统故障","发动机润滑系统故障"],"answer":[1],"image":"img/q235.jpg","tip":"","explanation":"看图中仪表板上是水温指示灯，车辆启动后一直亮起，说明发动机温度过高，可能是冷却液不足，需要停车检查。"},{"id":236,"type":"单选题","question":"如下图所示这个符号的开关控制什么装置？","options":["儿童安全锁","两侧车窗玻璃","电动车门","车门锁住开锁"],"answer":[3],"image":"img/q236.jpg","tip":"","explanation":"图中符号盒子里有一把钥匙，是车门锁住开锁标志。"},{"id":237,"type":"单选题","question":"以下哪个仪表表示发动机转速表？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[0],"image":"img/q237.jpg","tip":"","explanation":"题干问转速表，图中找x1000r/min，即图A。其他三项图B是速度和里程表，图C是水温表，图D是燃油表。要注意选项与图片编号的对应关系。"},{"id":238,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["防抱死制动系统故障","驻车制动器处于解除状态","安全气囊处于故障状态","行车制动系统故障"],"answer":[0],"image":"img/q238.jpg","tip":"","explanation":"看图中仪表板上的灯，圆圈里有个“ABS”是防抱死制动系统故障标志。"},{"id":239,"type":"单选题","question":"机动车仪表板上这个符号如下图所示表示什么？","options":["冷风暖气风扇","空调制冷","空气循环","雪地起步模式"],"answer":[0],"image":"img/q239.jpg","tip":"","explanation":"图中仪表板上的符号像个扇叶，是冷风暖气风扇，想要冷气或暖气都按它。"},{"id":240,"type":"单选题","question":"发动机起动后仪表板上如图所示指示灯亮表示什么？","options":["油箱内燃油已到最低液面","发动机供油系统出现异常","发动机点火系统出现故障","燃油泵出现异常或者故障"],"answer":[0],"image":"img/q240.jpg","tip":"","explanation":"看图中仪表板上是燃油指示灯，车辆启动后一直亮起，说明油箱内燃油已到最低液面，要尽快加油。"},{"id":241,"type":"单选题","question":"下列哪个指示灯亮表示车辆在使用近光灯？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[2],"image":"img/q241.jpg","tip":"","explanation":"题干问近光灯，图中找光线在左且为绿色倾斜线的，即图C。注意看清选项和图片编号的对应关系。"},{"id":242,"type":"单选题","question":"路口转弯过程中，持续开启转向灯，主要是因为？","options":["让其他驾驶人知道您在超车","完成转弯动作前，关闭转向灯会对车辆造成损害","让其他驾驶人知道您正在转弯","完成转弯动作前，关闭转向灯是习惯动作"],"answer":[2],"image":null,"tip":"","explanation":"路口转弯时，为提醒其他驾驶人知道您正在转弯，要持续开启转向灯，直至转弯完毕后，才可关闭转向灯。"},{"id":243,"type":"判断题","question":"开启危险报警闪光灯时，如下图所示指示灯闪烁。","options":["正确","错误"],"answer":[0],"image":"img/q243.jpg","tip":"","explanation":"图中仪表板上的双红三角是危险报警闪光灯，当车辆发生故障时，需要人工按键开启，才会闪烁。"},{"id":244,"type":"判断题","question":"驾驶人将机动车交给驾驶证被吊销的人驾驶的，交通警察可以依法吊销驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"驾驶证被吊销，相当于无证，绝对不能上路行驶。把机动车交由驾驶证被吊销的人驾驶，会追究连带责任，交警可依法吊销车主驾驶证，并处200-2000元罚款。"},{"id":245,"type":"单选题","question":"以下缩写中，表示车辆自适应巡航系统缩写的是什么？","options":["BSD","ACC","AEB","FCW"],"answer":[1],"image":null,"tip":"","explanation":"自适应巡航系统的英文缩写是ACC。"},{"id":246,"type":"单选题","question":"申请人隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，会受到什么处罚？","options":["处两千元以下罚款，申请人在一年内不得再次申领机动车驾驶证","处五百元以下罚款，申请人在一年内不得再次申领机动车驾驶证","处五百元以上两千元以下罚款，申请人终身不得再次申领机动车驾驶证","申请人终身不得再次申领机动车驾驶证"],"answer":[1],"image":null,"tip":"","explanation":"提供虚假材料申领驾驶证的，处500元以下罚款，一年不得再次申领。"},{"id":247,"type":"单选题","question":"以下缩写中，表示车辆车道偏离预警系统缩写的是什么？","options":["ALC","TSR","LDW","TMC"],"answer":[2],"image":null,"tip":"","explanation":"车道偏离预警系统的英文缩写是LDW。"},{"id":248,"type":"判断题","question":"驾驶载货汽车载物超过最大允许总质量未达到百分之三十的，一次记1分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"驾驶载货汽车超过最大允许载质量未达30%，一次记1分。"},{"id":249,"type":"判断题","question":"驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路、城市快速路以外的道路上行驶超过规定时速百分之五十以上的，一次记9分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶校车、危险品运输品等以外的机动车，在高速、城市快速路以外行驶超过规定时速50%以上，一次记6分。"},{"id":250,"type":"判断题","question":"行政处罚决定被依法变更或者撤销的，相应记分不会变更或者撤销。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"行政处罚依法变更或者撤销的，相应记分也会被变更或者撤销。"},{"id":251,"type":"单选题","question":"在最近几个记分周期内，机动车驾驶人饮酒后驾驶机动车受到过处罚的，不得通过接受交通安全教育扣减交通违法行为记分？","options":["1","2","3","4"],"answer":[2],"image":null,"tip":"","explanation":"注意在最近三个记分周期内，凡是因逃逸、饮酒、伪造、买卖分等受到处罚的，不得参加学法减分。"},{"id":252,"type":"判断题","question":"驾驶校车、中型以上载客载货汽车、危险物品运输车辆以外的机动车在高速公路上行驶超过规定时速百分之四十的，一次记6分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"超过规定时速40%，即20%-50%之间，一次记6分。"},{"id":253,"type":"单选题","question":"图中哪个报警灯亮，提示充电电路异常或故障？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[3],"image":"img/q253.jpg","tip":"","explanation":"题干问充电电路异常或故障灯，图中找正负极+-标志，即图D。其他三项图A是燃油指示灯，图B是制动系统异常标志，图C是ABS防抱死系统指示灯。要注意选项与图片编号的对应关系。"},{"id":254,"type":"单选题","question":"如图所示，怎样通过这样的路口？","options":["不减速通过","加速尽快通过","空挡滑行通过","减速或停车观察"],"answer":[3],"image":"img/q254.jpg","tip":"","explanation":"通过图中右侧标志得出，前方是无人看守的铁路道口，为安全起见，通过时要减速或停车观察，确认无火车驶来后即可通行。"},{"id":255,"type":"判断题","question":"机动车驾驶人在一个记分周期内累积记分满36分的，应当在道路交通安全法律、法规和相关知识考试合格后，按规定预约参加场地驾驶技能和道路驾驶技能考试。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在一个记分周期累积记分满36分的，参加法规学习考试合格后，再按规定参加科二科三考试。"},{"id":256,"type":"判断题","question":"驾驶机动车在高速公路加速车道上行驶，应尽快将车速提高到60km/h以上。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"车辆已经进入加速车道，要尽快将车速提高到60公里/小时。"},{"id":257,"type":"判断题","question":"驾驶机动车遇前方机动车停车排队或者缓慢行驶时，借道超车或者占用对面车道、穿插等候车辆的，一次记1分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶机动车遇前方机动车停车排队或者缓慢行驶时，借道超车或者占用对面车道、穿插等候车辆的，一次记3分。"},{"id":258,"type":"判断题","question":"驾驶机动车追逐竞驶、超员、超速、违反危险化学品安全管理规定运输危险化学品构成犯罪依法被吊销机动车驾驶证未满五年的，不得申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"因追逐竞驶被吊销驾驶证，5年内不得再次申领机动车驾驶证。"},{"id":259,"type":"判断题","question":"牵引与被牵引的机动车，在行驶中都要开启危险报警闪光灯。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"车辆发生故障需要被牵引时，车速相对较慢，所以牵引与被牵引车都要开启危险报警闪光灯，提醒其他车辆避让。"},{"id":260,"type":"判断题","question":"参加公安机关交通管理部门组织的道路交通安全法律、法规和相关知识网上学习三日内累计满三十分钟且考试合格的，一次扣减1分交通违法行为记分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"学法减分学习时，网上学习三天累计三十分钟，考试合格后，一次可以减1分。"},{"id":261,"type":"判断题","question":"饮酒后驾驶营运机动车依法被吊销机动车驾驶证未满五年的，不得申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"饮酒驾驶营运汽车被吊销驾驶证未满5年，不得再次申请机动车驾驶证。"},{"id":262,"type":"判断题","question":"机动车驾驶人补领机动车驾驶证后，原机动车驾驶证作废。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"驾驶证补领一般是证件遗失或损坏，领了新的自然原来的就作废，防止被其他不法分子利用。"},{"id":263,"type":"判断题","question":"黄色闪光警告信号灯持续闪烁，警示驾驶人要注意瞭望，确认安全通过。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"黄色信号灯持续闪烁，警示驾驶人要注意瞭望，确认安全通过。"},{"id":264,"type":"判断题","question":"驾驶人驾驶有达到报废标准嫌疑机动车上路的，交通警察依法予以拘留。","options":["正确","错误"],"answer":[1],"image":null,"tip":"拼装、报废车上路，吊驾照罚款，200至2000。","explanation":"驾驶报废车上路有安全隐患，将罚款200-2000元，吊销驾驶证，收缴车辆并强制报废。题干说“拘留”是错的。"},{"id":265,"type":"判断题","question":"驾驶人违反交通运输管理法规发生重大事故致人死亡的处3年以上有期徒刑。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"重点看是否有逃逸，且是否因逃逸致人死亡。未逃逸：3年以下；逃逸或情节特别恶劣：3-7年；因逃逸致人死亡：7年以上。"},{"id":266,"type":"判断题","question":"准驾车型为小型自动挡汽车的，可以驾驶低速载货汽车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"C1准驾2/3/4，C2可驾自动挡，年满18就能考。","explanation":"小型自动挡汽车C2，只能驾驶C2相关车型，低速载货汽车属于C3，不可驾驶。"},{"id":267,"type":"判断题","question":"机动车驾驶人造成重大交通事故后逃逸，构成犯罪的，十年内不能申请机动车驾驶证。","options":["正确","错误"],"answer":[1],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"凡是逃逸的，终生不得重新申领驾驶证。（假一吊二撤三醉五逃终生）"},{"id":268,"type":"单选题","question":"这个仪表是何含义？","options":["发动机转速表","行驶速度表","区间里程表","百公里油耗表"],"answer":[0],"image":"img/q268.jpg","tip":"km/h速度，r/min转速，温度计是水温，油箱是燃油。","explanation":"看图中仪表盘上有x1000r/min，是发动机转速表。"},{"id":269,"type":"判断题","question":"机动车驾驶证有效期超过一年以上未换证的，驾驶证将被注销。","options":["正确","错误"],"answer":[0],"image":null,"tip":"换证居住地，自愿降级可换领，超期一年会注销。","explanation":"驾驶证有效期前90日内可申请换证，超过一年未换证会被注销。"},{"id":270,"type":"单选题","question":"这是什么操纵装置？","options":["驻车制动器操纵杆","节气门操纵杆","变速器操纵杆","离合器操纵杆"],"answer":[0],"image":"img/q270.jpg","tip":"球头变速器；柱形驻车制动器。","explanation":"驾驶位右侧靠后的黑色杆，是驻车制动器操纵杆，即手刹，停车时向上拉起可防止溜车。"},{"id":271,"type":"判断题","question":"仪表显示当前车速是20公里/小时。","options":["正确","错误"],"answer":[1],"image":"img/q271.jpg","tip":"km/h速度，r/min转速，温度计是水温，油箱是燃油。","explanation":"看图中仪表盘上有x1000r/min，是发动机转速表；指针指向2，代表发动机转速是2000转每分钟。题干说是“车速”是错的。"},{"id":272,"type":"判断题","question":"机动车发生财产损失交通事故，对应当自行撤离现场而未撤离造成交通堵塞的，可以对驾驶人处以200元罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"该撤不撤，责令撤离罚200。","explanation":"发生财产损失交通事故，未自行撤离造成交通堵塞的，交警可依法对驾驶人处以200元罚款。"},{"id":273,"type":"单选题","question":"这个开关控制机动车哪个部位？","options":["风窗玻璃除雾器","风窗玻璃刮水器","危险报警闪光灯","照明、信号装置"],"answer":[1],"image":"img/q273.jpg","tip":"看图答题，图中玻璃上有刮水器，就在选项中找“刮水器”。所以选“风窗玻璃刮水器”。","explanation":"图中操纵杆在转向盘右侧，是刮水器开关，控制风窗玻璃刮水器。"},{"id":274,"type":"判断题","question":"申请人患有癫痫病的，可以申领机动车驾驶证，但是驾驶时必须有人陪同。","options":["正确","错误"],"answer":[1],"image":null,"tip":"疾病影响驾驶，禁止申领驾照。","explanation":"癫痫病患者，一旦在开车途中发病，容易引发交通事故，有安全隐患，不可申领驾驶证。"},{"id":275,"type":"单选题","question":"这是什么踏板？","options":["加速踏板","离合器踏板","制动踏板","驻车制动器"],"answer":[1],"image":"img/q275.jpg","tip":"踏板：左离合，中制动，右加速。","explanation":"手动挡车辆脚下三个踏板，从左到右依次是离合、制动和加速踏板。图中问最左侧，是离合踏板。"},{"id":276,"type":"单选题","question":"如图所示，铁路道口禁止掉头的原因是什么？","options":["有铁路道口信号灯","铁路道口车流量大","容易引发事故","有铁路道口标志"],"answer":[2],"image":"img/q276.jpg","tip":"危险路段禁止倒掉停，随时观察勿扰他车。","explanation":"铁路道口路况复杂，掉头容易引发事故，万一此时火车驶来，后果不敢想象，所以禁止掉头。"},{"id":277,"type":"判断题","question":"对未按照国家规定投保交强险的车辆，交通警察可依法予以扣留。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"交强险是国家法律规定强制要交的保险，保证发生交通事故后获得相关赔偿，如未按规定投保，可依法扣留车辆直至投保后，并处保险费的二倍罚款。"},{"id":278,"type":"判断题","question":"酒后驾驶发生重大交通事故被依法追究刑事责任的人不能申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"酒驾或醉驾造成重大事故，构成犯罪的，依法追究刑事责任，吊销驾驶证，终生不得重新申请。谨记：开车不喝酒，喝酒不开车。"},{"id":279,"type":"判断题","question":"驾驶人持超过有效期的驾驶证可以在1年内驾驶机动车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"无证禁止驾车，违反依法追责。","explanation":"驾驶证过期立马作废，不得驾驶机动车，要在有效期满前九十日内申请换证。"},{"id":280,"type":"单选题","question":"指示标线的作用是什么？","options":["禁止通行","指示通行","限制通行","警告提醒"],"answer":[1],"image":null,"tip":"禁令限制，指示行进，指路方向。","explanation":"指示标线顾名思义就是起指示通行的作用，引导你怎样安全行驶。"},{"id":281,"type":"单选题","question":"驾驶机动车在没有中心线的道路上遇相对方向来车时怎样行驶？","options":["减速靠右行驶","借非机动车道行驶","紧靠路边行驶","靠路中心行驶"],"answer":[0],"image":null,"tip":"低速会车靠右行，保持距离减停让。","explanation":"没有中心线的道路相对较窄，会车时为避免发生碰撞，要减速靠右行驶。"},{"id":282,"type":"单选题","question":"这个标志是何含义？","options":["傍山险路","悬崖路段","注意落石","危险路段"],"answer":[2],"image":"img/q282.jpg","tip":"黄三角有山体：无落石傍山险路，有落石注意落石。","explanation":"黄牌标志内见到石头从山上落下，是注意落石警告标志。要注意区分傍山险路无落石。"},{"id":283,"type":"判断题","question":"已注册登记的机动车，改变机动车车身颜色的应到公安交通管理部门申请变更登记。","options":["正确","错误"],"answer":[0],"image":null,"tip":"看文字答题，题干中见到“登记”就选对。（例外情况5题：当出现“居住地”、“完税”或“不需”时选错）","explanation":"改变车身颜色后，车辆信息发生变化，与行驶证上信息不一致，要及时申请变更登记。"},{"id":284,"type":"判断题","question":"机动车发生轻微财产损失的交通事故，对应当自行撤离现场而未撤离的，交通警察有权责令当事人撤离现场。","options":["正确","错误"],"answer":[0],"image":null,"tip":"该撤不撤，责令撤离罚200。","explanation":"发生轻微交通事故，要先自行撤离再协商解决。如未撤离造成交通拥堵的，交警可责令撤离，还可处以罚款。"},{"id":285,"type":"判断题","question":"当驾驶人的血液中酒精含量为100毫克/100毫升时，属于醉酒驾驶。","options":["正确","错误"],"answer":[0],"image":null,"tip":"20到80是酒驾：扣12分；80以上是醉驾：拘役罚款。","explanation":"血液中酒精含量≥80mg/100ml，属于醉酒驾驶；血液中酒精含量大于或等于20mg/100ml，小于80mg/100ml，属于饮酒驾驶。"},{"id":286,"type":"单选题","question":"这个标志是何含义？","options":["高速公路报警电话号码","高速公路交通广播频率","高速公路救援电话号码","高速公路服务电话号码"],"answer":[1],"image":"img/q286.jpg","tip":"看图答题，图中文字即含义。","explanation":"绿牌标志代表高速公路，有字母“kHz”和“道路交通信息”几个大字，是高速公路交通广播频率标志。"},{"id":287,"type":"单选题","question":"驾驶机动车通过窄路、窄桥时，最高速度不能超过多少？","options":["60公里/小时","50公里/小时","40公里/小时","30公里/小时"],"answer":[3],"image":null,"tip":"复杂路段、特殊天气、特殊操作，限速30。","explanation":"通过窄路、窄桥，由于路面宽度限制，车速不能超过30公里/小时。"},{"id":288,"type":"判断题","question":"造成交通事故后逃逸构成犯罪的人不能申请机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"造成事故凡是“逃逸”的，将会被吊销驾驶证，终生不得重新申请。（假一吊二撤三醉五逃终生）"},{"id":289,"type":"判断题","question":"道路交通安全违法行为累积记分一个周期满分为12分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"累积记分制度，周期12个月，满分12分。","explanation":"累积记分周期是一年，12个月，满分12分，从驾驶证初次领取日算起。"},{"id":290,"type":"判断题","question":"驾驶机动车上路行驶应当按规定悬挂号牌。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"机动车上路行驶，要按规定悬挂号牌。"},{"id":291,"type":"判断题","question":"已经达到报废标准的机动车经大修后也不可以上路行驶。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"已达到报废标准的机动车，有安全隐患，不能上路行驶。"},{"id":292,"type":"单选题","question":"这个标志是何含义？","options":["高速公路收费站预告","高速公路服务区预告","高速公路避险处预告","高速公路客车站预告"],"answer":[1],"image":"img/q292.jpg","tip":"高速绿底标志：只有P，停车场；有茶杯，停车区；有刀叉，服务区。","explanation":"图中标志有刀叉，在答案中找服务区。"},{"id":293,"type":"判断题","question":"代替实际机动车驾驶人参加审验教育的，由公安机关交通管理部门处二千元以下罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"代替驾驶人考试，处拘役或管制、并处或单处罚金；代替审验教育，罚款二千。","explanation":"代替实际驾驶人参加审验教育的，处2000元以下罚款。"},{"id":294,"type":"判断题","question":"驾驶人要按照驾驶证载明的准驾车型驾驶车辆。","options":["正确","错误"],"answer":[0],"image":null,"tip":"车型不同车况就不同，驾驶证是什么准驾车型就只能开什么车型。","explanation":"驾驶证上载明了准驾车型，驾驶人不可“跨级”驾驶。"},{"id":295,"type":"判断题","question":"伪造、变造或者使用伪造、变造驾驶证的驾驶人构成犯罪的，将依法追究刑事责任。","options":["正确","错误"],"answer":[0],"image":null,"tip":"构成犯罪，追究刑事责任。","explanation":"凡是“构成犯罪”的，都将依法追究刑事责任。此外，有伪造、变造或者使用伪造、变造的机动车驾驶证行为的，还会予以收缴，依法拘留，并处2000-5000元罚款。"},{"id":296,"type":"单选题","question":"这个导向箭头是何含义？","options":["指示前方右转弯","指示前方掉头","指示前方直行","指示向左变道"],"answer":[0],"image":"img/q296.jpg","tip":"看图答题，箭头偏向右边。所以选“指示前方右转弯”。","explanation":"看白色导向箭头方向向右，指示前方右转弯。"},{"id":297,"type":"判断题","question":"道路交通事故中，机动车无号牌、检验合格标志、保险标志时，要保护现场并立即报警。","options":["正确","错误"],"answer":[0],"image":null,"tip":"事故报警：撞公物、无牌标、动不了、伤亡、争议或酒驾。","explanation":"发生交通事故，机动车无号牌、无检验合格标志、无保险标志的，应当保护现场并立即报警，等待交警处理，不可自行协商处理。"},{"id":298,"type":"判断题","question":"发生交通事故后，当事人故意破坏、伪造现场、毁灭证据的，承担全部责任。","options":["正确","错误"],"answer":[0],"image":null,"tip":"判责：非故意都负责；故意、不礼让的负全责；掉货物的负全责。","explanation":"凡是逃逸、故意破坏，伪造现场、毁灭证据的，都要承担全部责任。"},{"id":299,"type":"判断题","question":"机动车之间发生的造成财产损失、尚未造成人员伤亡，且车辆可以移动的交通事故，双方驾驶人对交通事故无争议，但其中一方使用伪造、变造的号牌，不可以自行协商解决。","options":["正确","错误"],"answer":[0],"image":null,"tip":"看文字答题，题干中见到“伤亡”就选错。（例外情况4题：当出现“报警”、“无争议”时选对）","explanation":"使用伪造、变造的号牌是违法行为，违法就不是自行协商可以解决的。"},{"id":300,"type":"判断题","question":"驾驶机动车在上道路行驶前驾驶人要按规定系好安全带。","options":["正确","错误"],"answer":[0],"image":null,"tip":"门关好再起步，车停稳再开门，人员系安全带。","explanation":"安全带保障驾驶人生命安全，行车前必须按规定系好安全带。"},{"id":301,"type":"判断题","question":"打开前雾灯开关，（如图所示）亮起。","options":["正确","错误"],"answer":[1],"image":"img/q301.jpg","tip":"雾灯：斜光有遮挡，左前右后。","explanation":"看图中仪表板上的灯，有纵向线且为黄色光线向右，是后雾灯。题干说是“前雾灯”是错的。"},{"id":302,"type":"判断题","question":"驾驶未按规定定期进行安全技术检验的公路客运汽车、旅游客运汽车、危险物品运输车辆以外的机动车上道路行驶的，一次记1分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"小车不定期进行车检，扣1分。"},{"id":303,"type":"单选题","question":"如图所示，驾驶机动车遇到这种情形，以下做法正确的是什么？","options":["加速通过","鸣喇叭提醒行人让行","减速让行，必要时停车","变换远近光灯催促行人"],"answer":[2],"image":"img/q303.jpg","tip":"","explanation":"文明驾驶，礼让行人。"},{"id":304,"type":"判断题","question":"驾驶机动车在高速公路上行驶低于规定最低时速的，一次记3分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"高速上低于60，扣3分。"},{"id":305,"type":"判断题","question":"如图所示，驾驶机动车在这种路况下跟车距离较近时，应当开启远光灯照明。","options":["正确","错误"],"answer":[1],"image":"img/q305.jpg","tip":"","explanation":"跟车要用近光灯。"},{"id":306,"type":"判断题","question":"驾驶机动车在高速公路、城市快速路上穿越中央分隔带掉头的，一次记12分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在高速公路、城市快速路上倒车、逆行、穿越中央分隔带掉头的，一次记12分。"},{"id":307,"type":"判断题","question":"驾驶机动车不按规定超车、让行，或者在高速公路、城市快速路以外的道路上逆行的，一次记3分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"不按规定超车、让行，或者在高速公路、城市快速路以外的道路上逆行的，一次记3分。"},{"id":308,"type":"判断题","question":"如图所示，遇到这种情况的路段，不可以进入网状线区域内停车等候。","options":["正确","错误"],"answer":[0],"image":"img/q308.jpg","tip":"","explanation":"网状线都是黄色实线，不得停车。"},{"id":309,"type":"判断题","question":"在上一记分周期内机动车驾驶人有二次以上参加满分教育记录的，可以在接受交通安全教育后扣减交通违法行为记分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"上一记分周期内机动车驾驶人有二次以上参加满分教育记录的，不得接受交通安全教育后扣减交通违法行为记分。"},{"id":310,"type":"判断题","question":"机动车发生故障时，如下图所示指示灯闪烁。","options":["正确","错误"],"answer":[1],"image":"img/q310.jpg","tip":"","explanation":"图中仪表板上的双红三角是危险报警闪光灯，当车辆发生故障时，需要人工按键开启，并不会自动闪烁。"},{"id":311,"type":"单选题","question":"如下图所示这个符号的开关控制什么装置？","options":["后风窗玻璃除霜或除雾","前风窗玻璃刮水器及洗涤器","后风窗玻璃刮水器及洗涤器","前风窗玻璃除霜或除雾"],"answer":[2],"image":"img/q311.jpg","tip":"","explanation":"图中符号是方形且带喷嘴，为后风窗玻璃刮水器及洗涤器。延展：扇形是前窗刮水器及洗涤器。"},{"id":312,"type":"单选题","question":"发动机起动后仪表板上如图所示指示灯亮表示什么？","options":["发动机机油压力过高","发动机主油道堵塞","发动机机油压力过低","发动机曲轴箱漏气"],"answer":[2],"image":"img/q312.jpg","tip":"","explanation":"看图中仪表板上的灯像个在滴油的油壶，表示该车发动机机油压力过低或油量不足。"},{"id":313,"type":"判断题","question":"开启前照灯近光时仪表板上如下图所示指示灯亮起。","options":["正确","错误"],"answer":[1],"image":"img/q313.jpg","tip":"","explanation":"看图中仪表板上的灯，光线为蓝色平行线，是远光灯。题干说“近光”是错的。"},{"id":314,"type":"判断题","question":"机动车仪表板上如下图所示指示灯亮表示发动机可能机油压力过高。","options":["正确","错误"],"answer":[1],"image":"img/q314.jpg","tip":"","explanation":"看图中仪表板上的灯像个在滴油的油壶，表示该车发动机机油压力过低或油量不足。题干说“压力过高”是错的。"},{"id":315,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮时提醒发动机需要加注机油。","options":["正确","错误"],"answer":[1],"image":"img/q315.jpg","tip":"","explanation":"看图中仪表板上是水温指示灯，车辆启动后一直亮起，说明发动机温度过高，可能是冷却液不足，需要停车检查。题干说“加注机油”是错的。"},{"id":316,"type":"单选题","question":"进入这个路口应该怎样做？","options":["交替变换远、近光灯提醒路口内车辆让行","从路口内车辆前迅速插入","让已在路口内的车辆先行","鸣喇叭直接进入路口"],"answer":[2],"image":"img/q316.jpg","tip":"","explanation":"图中蓝色标志提醒前方进入环岛，按照通行原则，要让已在路口内的车辆先行。"},{"id":317,"type":"单选题","question":"如图所示，驾驶机动车在路口直行遇到这种信号灯应该怎样行驶？","options":["不得越过停止线","加速直行通过","左转弯行驶","进入路口等待"],"answer":[0],"image":"img/q317.jpg","tip":"","explanation":"红灯停，绿灯行，黄灯亮了您要等一等。图中信号灯是红灯，车辆不得越过停止线。"},{"id":318,"type":"单选题","question":"机动车仪表板上如下图所示指示灯亮表示什么？","options":["空气内循环","侧面出风","空气外循环","迎面出风"],"answer":[3],"image":"img/q318.jpg","tip":"","explanation":"图中仪表板上箭头代表出风方向，朝向人脸，表示迎面出风。"},{"id":319,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["没有系好安全带","安全带出现故障","已经系好安全带","安全带系得过松"],"answer":[0],"image":"img/q319.jpg","tip":"","explanation":"看图中仪表板上是安全带指示灯，一直亮起，说明没系好安全带。"},{"id":320,"type":"判断题","question":"机动车仪表板上如图所示指示灯一直亮，表示发动机控制系统故障。","options":["正确","错误"],"answer":[0],"image":"img/q320.jpg","tip":"","explanation":"图中仪表板上像个水龙头还有一道闪电，是发动机控制系统故障指示灯。"},{"id":321,"type":"判断题","question":"机动车在抵押登记、质押备案期间不可以办理转移登记。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"抵押登记、质押备案期间的机动车，不可以申请转让登记。"},{"id":322,"type":"判断题","question":"机动车驾驶人在一个记分周期内累积记分满24分未满36分的，应当在道路交通安全法律、法规和相关知识考试合格后，按规定预约参加场地驾驶技能考试。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"一个记分周期累积满24分未满36分的，应当在道路交通安全法律、法规和相关知识考试合格后，按规定预约参加道路驾驶技能考试，而不是场地驾驶技能考试。"},{"id":323,"type":"单选题","question":"下列哪个标志提示驾驶人连续弯路？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[1],"image":"img/q323.jpg","tip":"","explanation":"题干问“连续弯路”标志，图中找三个弯，即图B，其他三项：图A是向左急转弯标志，图C是反向弯路标志，图D是环形交叉标志。"},{"id":324,"type":"单选题","question":"车辆发生意外，要及时打开哪个灯？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[3],"image":"img/q324.jpg","tip":"","explanation":"车辆发生意外后，要开启危险报警闪光灯，图中找双红三角灯，即图D。其他三项图A是示廓灯，图B是前后雾灯，图C是远光灯。要注意选项与图片编号的对应关系。"},{"id":325,"type":"单选题","question":"在图中所示，同向三车道高速公路上行车，车速高于每小时110公里的车辆应在哪条车道上行驶？","options":["中间车道","最右侧车道","最左侧车道","哪条都行"],"answer":[2],"image":"img/q325.jpg","tip":"","explanation":"看图中车道上方绿色标志，标明了各条车道最高和最低时速，每小时115公里应该走最左侧车道。"},{"id":326,"type":"判断题","question":"驾驶不按规定安装机动车号牌的机动车上道路行驶的，一次记1分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶不按规定安装机动车号牌的机动车上道路行驶的，一次记3分。"},{"id":327,"type":"单选题","question":"以下哪个仪表表示速度和里程表？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[1],"image":"img/q327.jpg","tip":"","explanation":"题干问速度和里程表，图中找km/h，即图B。其他三项图A是转速表，图C是水温表，图D是燃油表。要注意选项与图片编号的对应关系。"},{"id":328,"type":"判断题","question":"遇到这个标志时，您应该主动确认您与前车之间的距离。","options":["正确","错误"],"answer":[0],"image":"img/q328.jpg","tip":"","explanation":"黄牌三角形标志内见到车行道上有两个“^”，是注意保持车距警告标志，提醒驾驶人注意和前车保持安全距离。"},{"id":329,"type":"单选题","question":"这个标志是何含义？","options":["禁止直行和向左转弯","禁止直行和向左变道","允许直行和向左变道","禁止直行和向右转弯"],"answer":[0],"image":"img/q329.jpg","tip":"","explanation":"红圈斜杠+直行和左转箭头，是禁止直行和向左转弯标志，表示前方路口禁止一切车辆直行和左转。"},{"id":330,"type":"单选题","question":"下列哪个标志，指示车辆直行和右转合用车道？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[0],"image":"img/q330.jpg","tip":"","explanation":"题干问“直行和右转合用车道”标志，图中找蓝底带虚线+直行和右转箭头，即图A，其他三项：图B是干路先行标志，图C是右转车道标志，图D是分向行驶车道标志。"},{"id":331,"type":"判断题","question":"机动车在道路上发生的造成财产损失、尚未造成人员伤亡，且车辆可以移动的交通事故，必须等待交通警察处理。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"在道路上发生交通事故，未造成人身伤亡，车辆可以移动的，当事人应当先撤离现场再进行协商处理，避免造成交通拥堵。"},{"id":332,"type":"判断题","question":"机动车驾驶人在驾驶证有效期满换领驾驶证时，可以到具有健康体检资质的二级以上医院、乡镇卫生院、社区卫生服务中心、健康体检中心等医疗机构体检。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"期满换证的身体条件证明，可以由具有健康体检资质的医疗机构提供。"},{"id":333,"type":"单选题","question":"如图所示，车辆在拥挤路段排队行驶时，遇有其他车辆强行穿插行驶，为保证安全，应怎么办？","options":["迅速躲避","提高车速不让其穿插","减速或停车让行","持续鸣喇叭警告"],"answer":[2],"image":"img/q333.jpg","tip":"","explanation":"拥堵路段遇到其他车辆强行穿插，为避免发生碰撞，要减速或停车让行。文明驾驶，礼貌让行。"},{"id":334,"type":"单选题","question":"行车中遇到后方车辆要求超车时，应怎样做？","options":["在条件许可的情况下，降低速度靠右让路","保持原有车速行驶","立即减速，靠右侧行驶","不让行"],"answer":[0],"image":null,"tip":"","explanation":"和谐社会，文明行车，礼貌让行。遇到后方车辆要求超车，要及时减速、观察后靠右让行。"},{"id":335,"type":"单选题","question":"下列哪个标志为最低限速标志？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[1],"image":"img/q335.jpg","tip":"","explanation":"题干问“最低限速”标志，图中找圆形蓝底白数字，即图B，表示最低限速50公里/小时，其他三项：图A是鸣喇叭标志，图C是机动车行驶标志，图D是非机动车行驶标志。"},{"id":336,"type":"判断题","question":"发动机号码、车辆识别代号因磨损、锈蚀、事故等原因辨认不清或者损坏的，可以向登记地车辆管理所申请备案。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"车辆识别代号因磨损等原因辨认不清或者损坏的，要到登记地车管所报备。"},{"id":337,"type":"判断题","question":"如图所示，驾驶机动车要选择绿色箭头灯亮的车道行驶。","options":["正确","错误"],"answer":[0],"image":"img/q337.jpg","tip":"","explanation":"图中绿色箭头灯亮时，准许本车道车辆按指示方向通行。"},{"id":338,"type":"判断题","question":"年龄在70周岁以上的机动车驾驶人发生责任交通事故造成人员重伤或者死亡的，应当在本记分周期结束后30日内到公安机关交通管理部门接受审验。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"年满70周岁驾驶机动车造成人员重伤或死亡，应接受审验，确认是否可以继续驾驶机动车。"},{"id":339,"type":"判断题","question":"驾驶机动车不按规定会车，或者在高速公路、城市快速路以外的道路上不按规定倒车、掉头的，一次记3分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶机动车不按规定会车，或者在高速公路、城市快速路以外的道路上不按规定倒车、掉头的，一次记1分。"},{"id":340,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮，提示两侧车门未关闭。","options":["正确","错误"],"answer":[0],"image":"img/q340.jpg","tip":"","explanation":"图中仪表板上黄色车辆明显两侧车门未关闭，提醒驾驶员要关好车门再起步。"},{"id":341,"type":"单选题","question":"下列哪个标志提示驾驶人下陡坡？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[3],"image":"img/q341.jpg","tip":"","explanation":"题干问“下陡坡”标志，图中找一个斜向下的箭头，即图D，其他三项：图A是向左急转弯标志，图B是连续弯路标志，图C是反向弯路标志。"},{"id":342,"type":"判断题","question":"机动车驾驶人在一个记分周期内累积记分未满12分，但有罚款逾期未缴纳的，该记分周期内尚未缴纳罚款的交通违法行为记分分值转入下一记分周期。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"一个记分周期累计记分未满12分的，但是有罚款没交，会计入一个记分周期。"},{"id":343,"type":"判断题","question":"驾驶机动车通过未划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在没有划分车道的路段，行人在两边行走，机动车在中间行驶。"},{"id":344,"type":"判断题","question":"机动车的型号或者有关技术参数与国务院机动车产品主管部门公告不符的，不予办理注册登记。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"机动车型号或技术参数与公告不符的，不予办理注册登记。"},{"id":345,"type":"判断题","question":"对行驶中的公共交通工具的驾驶人员使用暴力或者抢控驾驶操纵装置，干扰公共交通工具正常行驶，危及公共安全，构成犯罪的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"使用暴力或者抢控驾驶操纵装置，干扰公共交通工具正常行驶，危及公共安全的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"id":346,"type":"判断题","question":"驾驶人员在行驶的公共交通工具上擅离职守，与他人互殴或者殴打他人，危及公共安全，构成犯罪的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"题目描述的行为是严重的违法行为，且构成犯罪，涉及刑法，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。"},{"id":347,"type":"单选题","question":"如图所示，这位驾驶人违反法律规定的行为是什么？","options":["没按规定握转向盘","座椅角度不对","没系安全带","驾驶姿势不正确"],"answer":[2],"image":"img/q347.jpg","tip":"","explanation":"图中女驾驶员明显未系安全带，违反了《道路交通安全法》。"},{"id":348,"type":"判断题","question":"在行驶中，机动车驾驶人要注意与前车保持安全距离。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"距离产生美，行车时要与前车保持足够的安全距离，否则追尾可是后车全责。"},{"id":349,"type":"单选题","question":"机动车仪表板上如下图指示灯亮表示什么？","options":["两侧车门开启","行李舱开启","发动机舱开启","燃油箱盖开启"],"answer":[0],"image":"img/q349.jpg","tip":"","explanation":"图中仪表板上黄色车辆明显两侧车门开启，提醒驾驶员要关好车门再起步。"},{"id":350,"type":"单选题","question":"在堵车的交叉路口绿灯亮时，车辆应怎样做？","options":["可直接驶入交叉路口","不能驶入交叉路口","可借对向车道通过路口","在保证安全的情况下驶入交叉路口"],"answer":[1],"image":null,"tip":"路口观察减速行，拥堵依次交替走；排队停在路口外，依次停车等放行。","explanation":"前方交叉路口拥堵，为了不“添堵”，要依次停在路口外等候，即使是绿灯，也不能驶入。"},{"id":351,"type":"单选题","question":"这个标志是何含义？","options":["直行车道","只准直行","单行路","禁止直行"],"answer":[1],"image":"img/q351.jpg","tip":"看图答题，图中向上的箭头表示直行，蓝色的圆形图案是指示标志，指示直行表示“只准直行”。","explanation":"圆形蓝底+直行箭头，是只准直行标志。单行路是长方形蓝底，注意区分。"},{"id":352,"type":"单选题","question":"这个标志是何含义？","options":["公交车专用车道","BRT车辆专用车道","大型客车专用车道","多乘员车专用车道"],"answer":[1],"image":"img/q352.jpg","tip":"矩形蓝底、两侧虚线，有什么车型或箭头就是什么车道。","explanation":"图中长方形蓝底标志，两侧虚线中间有“快速公交”字样，是BRT车辆专用车道标志，表示该车道只供BRT车辆行驶。"},{"id":353,"type":"判断题","question":"如图所示，A车在此处停车是可以的。","options":["正确","错误"],"answer":[0],"image":"img/q353.jpg","tip":"口五站三不得停。","explanation":"图中A车距离公交车站30米，是可以停车的。巧记：站30口50，不得停车。"},{"id":354,"type":"单选题","question":"如图所示，驾驶机动车驶出这个路口时应当怎样使用灯光？","options":["开启右转向灯","开启危险报警闪光灯","不用开启转向灯","开启左转向灯"],"answer":[0],"image":"img/q354.jpg","tip":"环岛外让环岛内，进环岛不打灯，出环岛开右转。","explanation":"图中该机动车即将驶出环岛，要提前开右转向灯。"},{"id":355,"type":"判断题","question":"大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶人应当每两年提交一次身体条件证明。","options":["正确","错误"],"answer":[1],"image":null,"tip":"AB照每年审验，提交身体证明；有记分30日内审，无记分免审验。","explanation":"大、中型客货车驾驶人每年参加审验，审验时自己申报身体条件情况，但是没有记分的，该周期内可以免予审验。"},{"id":356,"type":"单选题","question":"这一组交通警察手势是什么信号？","options":["靠边停车信号","减速慢行信号","变道信号","右转弯信号"],"answer":[1],"image":"img/q356.jpg","tip":"手臂放身侧：左臂下压，左弯待转；右臂下压，减速慢行。","explanation":"图中交警右臂向右前方平伸，掌心向下，然后向下方45度摆动，是减速慢行信号，表示交警面向方向的车辆应减速慢行。"},{"id":357,"type":"判断题","question":"机动车驾驶证有效期分为6年、10年、20年。","options":["正确","错误"],"answer":[1],"image":null,"tip":"初领6年，无满分记录可换发10年、长期。","explanation":"驾驶证有效期分为六年、十年和长期，初次申领是六年。"},{"id":358,"type":"判断题","question":"驾驶人违反交通运输管理法规发生重大事故后，因逃逸致人死亡的，处3年以上7年以下有期徒刑。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"重点看是否有逃逸，且是否因逃逸致人死亡。未逃逸：3年以下；逃逸或情节特别恶劣：3-7年；因逃逸致人死亡：7年以上。"},{"id":359,"type":"单选题","question":"驾驶机动车在没有道路中心线的狭窄山路怎样会车？","options":["速度慢的先行","重车让空车先行","靠山体的一方先行","不靠山体的一方先行"],"answer":[3],"image":null,"tip":"狭窄山路会车，不靠山体的一方相对危险。所以选“不靠山体先行”。","explanation":"狭窄山路会车，不靠山体的一方相对危险，具有优先通行权，可先行。"},{"id":360,"type":"判断题","question":"机动车仪表板上（如图所示）亮，表示驻车制动器操纵杆可能没松到底。","options":["正确","错误"],"answer":[1],"image":"img/q360.jpg","tip":"看图答题，图中仪表盘上的灯，圆圈里有个“！”是制动系统出现异常标志。与驻车制动器无关。所以选错。","explanation":"看图中仪表板上的灯，圆圈里有个“！”是制动系统出现异常标志，与驻车制动器无关。"},{"id":361,"type":"单选题","question":"安全气囊是一种什么装置？","options":["驾驶人头颈保护系统","防抱死制动系统","电子制动力分配系统","辅助驾乘人员保护系统"],"answer":[3],"image":null,"tip":"气囊辅助安全带，保护人员减伤害。","explanation":"安全气囊是辅助驾乘人员保护系统，当车辆发生碰撞时，气囊会迅速膨胀，在驾驶人、乘车人的正面和侧面形成保护气垫，从而降低驾乘人员伤害程度。"},{"id":362,"type":"单选题","question":"这个导向箭头是何含义？","options":["提示前方有左弯或需向左合流","提示前方有右弯或需向右合流","提示前方右侧有障碍或需向左合流","提示前方有左弯或需向左绕行"],"answer":[0],"image":"img/q362.jpg","tip":"白箭头略弯曲、倾斜，提示有弯或合流。","explanation":"看白色导向箭头微微向左倾斜，提示前方有左弯或需向左合流。"},{"id":363,"type":"单选题","question":"安全头枕在发生追尾事故时，能有效保护驾驶人的什么部位？","options":["腰部","胸部","颈部","头部"],"answer":[2],"image":null,"tip":"头枕保护颈部，调至与头平齐；安全带固定身体，过肩固定在胯。","explanation":"安全头枕是用来保护驾驶员颈部的，头枕顶部要与头平齐，中央对准脑后部。"},{"id":364,"type":"判断题","question":"这个标志的含义是提醒车辆驾驶人前方是堤坝路段。","options":["正确","错误"],"answer":[1],"image":"img/q364.jpg","tip":"黄三角有山体：无落石傍山险路，有落石注意落石。","explanation":"黄色三角形内有一座大山，是傍山险路警告标志，提醒驾驶人小心行车。题干说“堤坝路”是错的。"},{"id":365,"type":"单选题","question":"驾驶机动车行经市区下列哪种道路时不得超车？","options":["主要街道","单向行驶路段","单向两条行车道","交通流量大的路段"],"answer":[3],"image":null,"tip":"危险路段、对向有车、前车向左或不让、遇执行公务的特种车，不能超车。","explanation":"市区交通流量大的路段，没有足够的安全距离，不具备超车条件，不得超车。"},{"id":366,"type":"单选题","question":"这个路面标记是何含义？","options":["自行车专用道","非机动车道","摩托车专用道","电瓶车专用道"],"answer":[1],"image":"img/q366.jpg","tip":"路面自行车，非机动车道。","explanation":"图中路面标记是个自行车，表示非机动车道。"},{"id":367,"type":"单选题","question":"这辆在道路上行驶的机动车有下列哪种违法行为？","options":["逆向行驶","未按规定悬挂号牌","故意遮挡号牌","占用非机动车道"],"answer":[2],"image":"img/q367.jpg","tip":"号牌相关：假证假牌12分，遮挡不挂扣9分，违规安装扣3分。","explanation":"图中机动车故意遮挡号牌，是违法行为，一次记9分。"},{"id":368,"type":"判断题","question":"这个标志的作用是用以警告车辆驾驶人谨慎慢行，注意横向来车。","options":["正确","错误"],"answer":[0],"image":"img/q368.jpg","tip":"交叉路口看图形，横向来车多注意。","explanation":"黄色三角形内有一个十字，是十字交叉警告标志，用以警告驾驶人谨慎慢行，注意横向来车。"},{"id":369,"type":"单选题","question":"这个标志是何含义？","options":["非机动车车道","禁止自行车通行车道","自行车专用车道","停放自行车路段"],"answer":[0],"image":"img/q369.jpg","tip":"矩形蓝底、两侧虚线，有什么车型或箭头就是什么车道。","explanation":"图中长方形蓝底标志，两侧虚线中间有一辆自行车，是非机动车车道标志，表示该车道只供非机动车行驶。"},{"id":370,"type":"判断题","question":"驾驶人在道路上醉酒驾驶机动车的处3年以上有期徒刑。","options":["正确","错误"],"answer":[1],"image":null,"tip":"20到80是酒驾：扣12分；80以上是醉驾：拘役罚款。","explanation":"醉酒驾驶机动车要处拘役，并处罚金。此外还会吊销驾驶证，五年内不得再次申领。"},{"id":371,"type":"单选题","question":"这是什么操纵装置？","options":["除雾器开关","转向灯开关","前照灯开关","刮水器开关"],"answer":[3],"image":"img/q371.jpg","tip":"看图答题，方向盘的左右操纵杆，左灯右水，图中手柄在右边，表示“刮水器开关”。","explanation":"图中操纵杆在转向盘右侧，是刮水器开关。"},{"id":372,"type":"单选题","question":"这个标志是何含义？","options":["高速公路起点预告","高速公路出口预告","高速公路入口预告","高速公路终点预告"],"answer":[3],"image":"img/q372.jpg","tip":"高速绿底标志，有红杠是终点，无红杠是起点。","explanation":"高速公路起点和终点标志，仅一线之差。无红色斜线的是高速公路起点预告，有红色斜线的是高速公路终点预告，要注意区分。"},{"id":373,"type":"单选题","question":"假如你驾车行驶在颠簸路段时，以下做法正确的是什么？","options":["稳住加速踏板","挂低挡位缓抬加速踏板","挂高挡位缓抬加速踏板","挂低挡位踏满加速踏板"],"answer":[1],"image":null,"tip":"颠簸不平低挡过。","explanation":"行经颠簸路段一定要“稳”，挂低挡，缓抬加速踏板，低速通过。"},{"id":374,"type":"单选题","question":"这属于哪一种标志？","options":["警告标志","禁令标志","指示标志","指路标志"],"answer":[2],"image":"img/q374.jpg","tip":"黄警告，红禁令，指示多为蓝圈，指路写清地点。","explanation":"交通标志按颜色区分类型：黄牌-警告标志，红牌-禁令标志，蓝牌-指示标志。"},{"id":375,"type":"判断题","question":"这个标志的含义是前方即将行驶至Y形交叉路口。","options":["正确","错误"],"answer":[1],"image":"img/q375.jpg","tip":"交叉路口看图形，横向来车多注意。","explanation":"黄色三角形内有一个向左倒的T字，是T形交叉路口警告标志，提醒驾驶人前方要谨慎慢行，注意横向来车。题干说“Y形”是错的。"},{"id":376,"type":"判断题","question":"这个标志的含义是告示前方是拥堵路段，注意减速慢行。","options":["正确","错误"],"answer":[1],"image":"img/q376.jpg","tip":"风吹飘带有横风，有房有树是村庄，人在铲土施工路，两车相撞事故多。","explanation":"黄色三角形内有两车相撞，是事故易发路段警告标志，提醒驾驶人谨慎行车。题干说“拥堵路段”是错的。"},{"id":377,"type":"单选题","question":"这个导向箭头是何含义？","options":["指示前方可左转或掉头","指示前方可直行或左转","指示前方可直行或掉头","指示前方直行向左变道"],"answer":[2],"image":"img/q377.jpg","tip":"看图答题，图中箭头既有向前又有掉头，所以选“直行或掉头”。","explanation":"看白色导向箭头方向是直行和掉头，指示前方道路可直行或掉头。"},{"id":378,"type":"单选题","question":"这个路面数字标记是何含义？","options":["保持车距标记","最小间距标记","速度限制标记","道路编号标记"],"answer":[2],"image":"img/q378.jpg","tip":"看图答题，图中数字表示速度，所以选“速度限制标记”。","explanation":"图中路面数字是速度限制标记，根据数字颜色区分：黄色是最高限速，白色是最低限速。"},{"id":379,"type":"单选题","question":"驾驶机动车在冰雪道路行驶时，最高速度不能超过多少？","options":["20公里/小时","30公里/小时","40公里/小时","50公里/小时"],"answer":[1],"image":null,"tip":"复杂路段、特殊天气、特殊操作，限速30。","explanation":"冰雪道路行驶，车轮与地面摩擦力减小，容易打滑，车速不能超过30公里/小时。"},{"id":380,"type":"单选题","question":"这是什么操纵装置？","options":["除雾器开关","转向灯开关","前照灯开关","刮水器开关"],"answer":[0],"image":"img/q380.jpg","tip":"看图答题，图中在扇形和矩形的白色标志上有弯曲的箭头，表示玻璃上有雾气了，扇形代表前玻璃，矩形代表后玻璃，这个按键是用来除雾的。所以选“除雾器开关”。","explanation":"图中装置内曲线向上箭头表示雾气，该装置是除雾器开关。扇形为前，矩形为后。"},{"id":381,"type":"单选题","question":"驾驶机动车变更车道时，以下做法正确的是什么？","options":["开启转向灯的同时变更车道","在道路同方向划有2条以上机动车道的，不得影响相关车道内行驶的机动车的正常行驶","在车辆较少路段，可以随意变更车道","遇前方道路拥堵，可以向应急车道变更"],"answer":[1],"image":null,"tip":"方向改变，左右转向提前开；仔细观察，不压实线不扰他车。","explanation":"变更车道不能影响其他正常行驶车辆，提前开启左转向灯，确保有足够的安全距离后再变更。"},{"id":382,"type":"单选题","question":"路口最前端的双白实线是什么含义？","options":["等候放行线","停车让行线","减速让行线","左弯待转线"],"answer":[1],"image":"img/q382.jpg","tip":"路口白线：单实停止线，双实停车让，双虚减速让。","explanation":"靠近路口的白线有三类：单白横实线是停止线，双白横实线是停车让行线，双白横虚线是减速让行线。"},{"id":383,"type":"单选题","question":"图中圈内的路面标记是什么标线？","options":["路口示意线","停车让行线","减速让行线","人行横道线"],"answer":[3],"image":"img/q383.jpg","tip":"白色实线，多条平行，人行横道。","explanation":"多条平行的白实线组成了斑马线，即人行横道，作用是引导行人安全通过马路。"},{"id":384,"type":"单选题","question":"这个标志是何含义？","options":["禁止左转","此路不通","禁止通行","超高绕行"],"answer":[3],"image":"img/q384.jpg","tip":"限高标志+绕行箭头，表示超高绕行。","explanation":"蓝牌内有限高标志+绕行线路，是超高绕行标志，表示高度超过4米的车辆需绕行，低于4米的可直行。"},{"id":385,"type":"判断题","question":"科目三考试分为道路驾驶技能考试和安全文明驾驶常识考试两部分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"科三考两门，驾驶技能和常识，达到九十分合格。","explanation":"科目三考试包含：道路驾驶技能和安全文明驾驶常识考试。"},{"id":386,"type":"单选题","question":"这个标志是何含义？","options":["40米减速行驶路段","最低时速40公里","解除时速40公里限制","最高时速40公里"],"answer":[2],"image":"img/q386.jpg","tip":"黑圈五斜杠，解除禁令。","explanation":"看标志的颜色，红色是禁令，黑色是解除禁令，图中是黑色+限速40公里，即为解除时速40公里限制标志。"},{"id":387,"type":"单选题","question":"机动车在道路边临时停车时，应怎样做？","options":["不得逆向或并列停放","只要出去方便，可随意停放","可逆向停放","可并列停放"],"answer":[0],"image":null,"tip":"停车要在停车位，不得逆向或并列，临时停不碍通行。","explanation":"在道路上临时停车，不得妨碍其他车辆和行人通行，不得逆向或并列停放。"},{"id":388,"type":"判断题","question":"这个标志的含义是指示此处设有室内停车场。","options":["正确","错误"],"answer":[0],"image":"img/q388.jpg","tip":"看图答题，一个“P”就是露天停车场，带个伞遮挡就是室内停车场。题干说“室内”。所以选对。","explanation":"蓝牌标志内P上带个伞，是室内停车场标志。延展：只有P的，是露天停车场。"},{"id":389,"type":"单选题","question":"如图所示，驾驶机动车遇到这种情况时，以下做法正确的是什么？","options":["应停车察明水情，确认安全后，低速通过","应停车察明水情，确认安全后，快速通过","应减速观察水情，然后加速行驶通过","可随意通行"],"answer":[0],"image":"img/q389.jpg","tip":"漫水路前，停车查路况，低速慢行禁空挡。","explanation":"图中前方是过水路面，要停车察明水情，确认安全后，低速通过。"},{"id":390,"type":"判断题","question":"图中左侧白色轿车，在这种情况下为了保证安全，应适当降低车速。","options":["正确","错误"],"answer":[0],"image":"img/q390.jpg","tip":"看文字答题，题干中见到“降低”就选对。","explanation":"图中右侧红圈白底是限速标志，表示该路段限速60公里/小时，从车辆仪表盘看出，该车车速已超过60，所以要适当降低车速。"},{"id":391,"type":"单选题","question":"在这种天气条件下行车如何使用灯光？","options":["使用远光灯","使用雾灯","开启右转向灯","不使用灯光"],"answer":[1],"image":"img/q391.jpg","tip":"雾天看不清，雾灯、双闪减速行，必要时候靠边停。","explanation":"图中是雾天能见度较低，为让其他车辆看到自己，要开启雾灯和危险报警闪光灯。"},{"id":392,"type":"判断题","question":"如图所示，当机动车行驶至交叉口时的做法是正确的。","options":["正确","错误"],"answer":[0],"image":"img/q392.jpg","tip":"红停绿行黄警示；没有箭头可右转。","explanation":"图中信号灯是圆形绿灯，A车所在车道允许右转，且提前开启了右转向灯，所以虚线行驶方向是正确的。"},{"id":393,"type":"单选题","question":"这个标志是何含义？","options":["停车场","观景台","休息区","服务区"],"answer":[2],"image":"img/q393.jpg","tip":"看图答题，图中文字即含义。","explanation":"图中蓝底标志内写着“休息区”，是休息区标志，表示前方有可供驾驶员停车休息的区域。"},{"id":394,"type":"单选题","question":"禁令标志的作用是什么？","options":["禁止或限制行为","告知方向信息","指示车辆行进","警告前方危险"],"answer":[0],"image":null,"tip":"禁令限制，指示行进，指路方向。","explanation":"既然是禁令标志，顾名思义一定禁止或限制车辆做某些行为。"},{"id":395,"type":"判断题","question":"如图所示，驾驶机动车遇到这种情况，可以轻按喇叭提醒前方非机动车和行人后方有来车。","options":["正确","错误"],"answer":[0],"image":"img/q395.jpg","tip":"看文字答题，题干中见到“轻”就选对。（例外情况2题：当出现“不需”或“必须”时选错）","explanation":"图中道路未划分车行道，为安全起见，可轻按喇叭，提醒前方机动车和行人后方有来车。"},{"id":396,"type":"判断题","question":"驾驶人在驾驶证丢失后3个月内还可以驾驶机动车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"无证禁止驾车，违反依法追责。","explanation":"驾驶证丢失未申请补发的都算无证，不得驾驶机动车。人无证不开车，车无证不上路。"},{"id":397,"type":"单选题","question":"这个标志是何含义？","options":["专用停车场","露天停车场","室内停车场","内部停车场"],"answer":[2],"image":"img/q397.jpg","tip":"看图答题，图中p带个伞，表示“室内停车场”。","explanation":"蓝牌标志内P上带个伞，是室内停车场标志。延展：只有P的，是露天停车场。"},{"id":398,"type":"判断题","question":"驾驶机动车造成重大交通事故后逃逸，构成犯罪的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"逃逸、酒驾构成犯罪，终生禁领驾照。","explanation":"凡是逃逸的，“终生”不得重新申领驾驶证。"},{"id":399,"type":"判断题","question":"持有大型客车、重型牵引挂车、城市公交车、中型客车、大型货车驾驶证的驾驶人，记分周期内有记分的，应当在记分周期结束后三十日内到公安机关交通管理部门接受审验，同时还应当申报身体条件情况。","options":["正确","错误"],"answer":[0],"image":null,"tip":"AB照每年审验，提交身体情况；有记分30日内审，无记分免审验。","explanation":"持有大型客车、重型牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人，有扣分的，要在记分周期结束后30天内接受审验，并提交体检报告，没扣分的可免检。"},{"id":400,"type":"单选题","question":"机动车在高速公路行驶，下列做法正确的是？","options":["非紧急情况时不得在应急车道行驶或者停车","可在减速车道或加速车道上超车、停车","可在紧急停车带停车装卸货物","可在路肩停车上下人员"],"answer":[0],"image":null,"tip":"高速禁止倒掉停，应急路肩勿占用，错过出口找下个。","explanation":"非紧急情况下，高速公路任何地点都不得停车；只要在紧急情况下，才可在应急车道上停车或行驶。"},{"id":401,"type":"单选题","question":"交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪？","options":["未带驾驶证","未报警","明知是无牌证或者已报废的机动车辆而驾驶的","未抢救受伤人员的"],"answer":[2],"image":null,"tip":"交通肇事罪：无准驾、隐患车、严重超载或酒毒、无牌报废或逃逸。","explanation":"1.酒驾或毒驾；2.无驾驶资格驾车；3.车辆有安全隐患；4.无牌车或报废车；5.严重超载；6.肇事逃逸。具有以上任意一种行为，且致人重伤，负全部或主要责任的，都是交通肇事罪。"},{"id":402,"type":"判断题","question":"机动车号牌损毁，机动车所有人要向登记地车辆管理所申请补领、换领。","options":["正确","错误"],"answer":[0],"image":null,"tip":"机动车相关证件，补、换、备案都找登记地。","explanation":"机动车号牌损毁的，要向登记地车辆管理所申请补领、换领。注意机动车相关的补领和换领，都找登记地。"},{"id":403,"type":"判断题","question":"驾驶机动车在道路上掉头时，应当提前开启左转向灯。","options":["正确","错误"],"answer":[0],"image":null,"tip":"方向改变，左右转向提前开；仔细观察，不压实线不扰他车。","explanation":"掉头是向左侧掉头，要提前开启左转向灯，告知后方车辆注意。"},{"id":404,"type":"判断题","question":"年龄在70周岁以上的机动车驾驶人，应当每年进行一次身体检查。","options":["正确","错误"],"answer":[0],"image":null,"tip":"70岁以上，每年体检排隐患，一年不交会注销。","explanation":"70周岁以上的驾驶人，要每一年提交一次身体证明，为自己也为他人安全着想。"},{"id":405,"type":"单选题","question":"驾驶机动车遇有前方交叉路口交通阻塞时怎么办？","options":["依次停在路口外等候","可借对向车道通过","从前车两侧穿插通过","进入路口内等候"],"answer":[0],"image":null,"tip":"路口观察减速行，拥堵依次交替走；排队停在路口外，依次停车等放行。","explanation":"前方路口拥堵，为了不添堵，要依次停在路口外等候。"},{"id":406,"type":"判断题","question":"对发生道路交通事故需要收集证据的事故车，交通警察可以依法扣留。","options":["正确","错误"],"answer":[0],"image":null,"tip":"收集证据事故车，交警依法可扣留。","explanation":"扣留事故车是为了收集证据，更好地解决事故问题，驾驶员要积极配合。"},{"id":407,"type":"判断题","question":"驾驶机动车通过漫水路时要加速行驶。","options":["正确","错误"],"answer":[1],"image":null,"tip":"漫水路前，停车查路况，低速慢行禁空挡。","explanation":"遇到漫水路面，不知道水深水浅，贸然通过车辆可能会进水，所以要先停车观察水情，确认安全后再低速通过。"},{"id":408,"type":"判断题","question":"当行人出现交通安全违法行为时，车辆可以不给行人让行。","options":["正确","错误"],"answer":[1],"image":null,"tip":"复杂路段减速行，遇人遇车要礼让，必要靠边停车让。","explanation":"任何情况下，机动车都要礼让行人、非机动车。文明驾驶，礼貌让行。"},{"id":409,"type":"判断题","question":"驾驶机动车上道路行驶，不允许超过限速标志标明的最高时速。","options":["正确","错误"],"answer":[0],"image":null,"tip":"超速行驶很危险，遵守交规保安全。所以选对。","explanation":"有限速标志，要按照限速标志行驶，不允许超速。"},{"id":410,"type":"判断题","question":"行车中，燃油报警灯亮，应及时到附近加油站加油，以免造成车辆乘员滞留公路，发生交通事故。","options":["正确","错误"],"answer":[0],"image":null,"tip":"燃油灯亮表示燃油不足，应及时补充。所以选对。","explanation":"燃油报警灯亮，说明车辆马上就要没油了，不尽快加油，可能会滞留公路，还会造成油泵损坏。"},{"id":411,"type":"判断题","question":"驾驶人有使用其他车辆号牌、行驶证嫌疑的，交通警察可依法扣留车辆。","options":["正确","错误"],"answer":[0],"image":null,"tip":"两证两标一号牌，不带扣车还罚款。","explanation":"凡是使用其他车辆证件（登记证书，行驶证）、号牌、标志（检验合格、保险）嫌疑的，交警会依法扣留车辆。"},{"id":412,"type":"判断题","question":"在没有交通信号指示的交叉路口，转弯的机动车让直行的车辆和行人先行。","options":["正确","错误"],"answer":[0],"image":null,"tip":"看文字答题，题干中见到“先行”就选对。（例外情况3题：当见到“先行撤离”或“会车”时选错）","explanation":"通行原则：右转让左转，左转让直行，转弯让直行。"},{"id":413,"type":"判断题","question":"机动车上路行驶时，前排乘车人可不系安全带。","options":["正确","错误"],"answer":[1],"image":null,"tip":"门关好再起步，车停稳再开门，人员系安全带。","explanation":"系安全带不分前后排，驾驶人、乘车人都要系好，否则就是违反《道路交通安全法》的行为。"},{"id":414,"type":"判断题","question":"驾驶车辆通过人行横道线时，应注意礼让行人。","options":["正确","错误"],"answer":[0],"image":null,"tip":"复杂路段减速行，遇人遇车要礼让，必要靠边停车让。","explanation":"驾驶机动车任何情况下，都要注意礼让行人。文明驾驶，礼貌让行。"},{"id":415,"type":"判断题","question":"驾驶机动车在高速公路上行驶，可以随时借用应急车道行驶、超车或停车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“借”就选错。（例外情况1题：当出现“借量”时选对）","explanation":"驾驶机动车在高速上行驶，非紧急情况时不得在应急车道行驶或者停车。"},{"id":416,"type":"单选题","question":"如图所示，驾驶机动车行驶至此路口时，以下做法正确的是什么？","options":["交替使用远近光灯警告行人","连续鸣喇叭催促行人快速通过","停车让行","加速从行人的身后通过"],"answer":[2],"image":"img/q416.jpg","tip":"","explanation":"文明驾驶，礼让行人。"},{"id":417,"type":"单选题","question":"在高速公路上驾驶机动车，以下做法正确的是什么？","options":["错过出口后继续行驶，从下一出口驶出","一次变更两条车道","遇前车行驶缓慢使用应急车道通行","在行车道停车"],"answer":[0],"image":null,"tip":"","explanation":"错过出口继续寻找；应急车道不能随意占用；车道一次只能变更一条；高速行车道不得停车。"},{"id":418,"type":"单选题","question":"如图所示，驾驶机动车在同方向只有1条机动车道的公路上行驶，最高行驶速度不得超过每小时多少公里？","options":["70","40","60","50"],"answer":[0],"image":"img/q418.jpg","tip":"","explanation":"同方向只有一条车道就是有中心线，城五公七。"},{"id":419,"type":"单选题","question":"驾驶机动车在高速公路上行驶，遇有能见度小于200米的恶劣气象条件时，车速不得超过每小时多少公里？","options":["50","60","40","30"],"answer":[1],"image":null,"tip":"","explanation":"高速上能见度小于200，车速不超过60，距离大于100。"},{"id":420,"type":"单选题","question":"如图所示，驾驶机动车行驶至铁路道口时，以下做法正确的是什么？","options":["在铁路道口掉头","在铁路道口倒车","无需观察，加速通过","停车等待"],"answer":[3],"image":"img/q420.jpg","tip":"","explanation":"红灯停，不得继续行驶。"},{"id":421,"type":"判断题","question":"如图所示，驾驶机动车可以在该路段通行。","options":["正确","错误"],"answer":[1],"image":"img/q421.jpg","tip":"","explanation":"红圈是禁令标志，中间有啥禁止啥，禁止机动车通行。"},{"id":422,"type":"单选题","question":"夜间驾驶机动车在高速公路上发生交通事故，以下做法正确的是什么？","options":["人员下车在原地等待处理交通事故","开启远光灯，在车内等待救援","开启危险报警闪光灯，人员转移到安全地带","关闭所有灯光，人员转移到右侧护栏以外"],"answer":[2],"image":null,"tip":"","explanation":"高速发生事故开启危险报警闪光灯，车后150米设置危险警告标志，车上人员转移到安全地带。"},{"id":423,"type":"判断题","question":"如图所示，这种情形下，A车可以继续通行。","options":["正确","错误"],"answer":[0],"image":"img/q423.jpg","tip":"","explanation":"黄灯越过停止线可继续通行。"},{"id":424,"type":"单选题","question":"夜间驾驶机动车会车时，应使用的灯光是什么？","options":["危险报警闪光灯","近光灯","远光灯","雾灯"],"answer":[1],"image":null,"tip":"","explanation":"会车使用近光灯。"},{"id":425,"type":"判断题","question":"如图所示，在没有划分道路中心线的道路上行驶，会车时必须减速靠右通过。","options":["正确","错误"],"answer":[0],"image":"img/q425.jpg","tip":"","explanation":"会车时，减速靠右，加大横向安全距离。"},{"id":426,"type":"判断题","question":"驾驶机动车行经人行横道不按规定减速、停车、避让行人的，一次记3分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"行经人行横道不按规定减速、停车、避让行人的，一次记3分。"},{"id":427,"type":"判断题","question":"在道路上遇到这种情况可以从左侧超车。","options":["正确","错误"],"answer":[1],"image":"img/q427.jpg","tip":"","explanation":"对向有来车，横向安全距离不够，不得超车。"},{"id":428,"type":"判断题","question":"在路口这个位置时可以右转通过路口。","options":["正确","错误"],"answer":[0],"image":"img/q428.jpg","tip":"","explanation":"只有一个红灯右转不受限制。"},{"id":429,"type":"判断题","question":"机动车驾驶人在实习期内驾驶机动车不得上高速公路行驶。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"实习期内有持相应或者包含其准驾车型驾驶证三年以上的驾驶人陪同可上高速。"},{"id":430,"type":"判断题","question":"如图所示，遇到这种情况的铁路道口，禁止车辆通行。","options":["正确","错误"],"answer":[0],"image":"img/q430.jpg","tip":"","explanation":"红灯停，遇到红灯不通行。"},{"id":431,"type":"判断题","question":"驾驶机动车违反禁令标志、禁止标线指示的，一次记6分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"违反禁令标志、禁止标线指示的，一次记1分。"},{"id":432,"type":"判断题","question":"如图所示，在交叉路口遇到这种情况时，应在停止线前等待，不可加速通过路口。","options":["正确","错误"],"answer":[0],"image":"img/q432.jpg","tip":"","explanation":"前方有车辆正在通过，且有停车让行标志，应停车等待。"},{"id":433,"type":"判断题","question":"如图所示，驾驶机动车行驶至此路段时，可在路边临时停车。","options":["正确","错误"],"answer":[1],"image":"img/q433.jpg","tip":"","explanation":"红圈中间有个叉，车辆不得停放。"},{"id":434,"type":"判断题","question":"如图所示，该机动车在行驶过程中存在违法行为。","options":["正确","错误"],"answer":[0],"image":"img/q434.jpg","tip":"","explanation":"遮挡号牌是违法行为。"},{"id":435,"type":"判断题","question":"如图所示，驾驶机动车遇左侧车道有车辆正在超车时，可以等待左侧车辆完成超车后，再寻找时机超车。","options":["正确","错误"],"answer":[0],"image":"img/q435.jpg","tip":"","explanation":"文明驾驶，先让其他车超。"},{"id":436,"type":"判断题","question":"驾驶机动车在地下车库寻找停车位时，应注意观察行人的动态，遇行人横穿车道时及时减速、停车避让。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"在停车场要按标识慢行观察四周，遇行人要及时减速停车避让。"},{"id":437,"type":"判断题","question":"打开前后雾灯开关，如下图所示指示灯亮起。","options":["正确","错误"],"answer":[1],"image":"img/q437.jpg","tip":"","explanation":"看图中仪表板上的灯，有纵向线且为绿色光线向左，是前雾灯。"},{"id":438,"type":"判断题","question":"交通警察对未放置保险标志上道路行驶的车辆可依法扣留行驶证。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"没有保险标志，会被扣车，不是行驶证。"},{"id":439,"type":"单选题","question":"驾驶装有ABS系统的汽车怎样采取紧急制动？","options":["缓慢踏制动踏版","用力踏制动踏板","间歇踏制动踏板","逐渐踏下制动踏板"],"answer":[1],"image":null,"tip":"","explanation":"有ABS就用力踩刹车。"},{"id":440,"type":"判断题","question":"组织他人参加审验教育时在签注学习记录、学习过程中弄虚作假的，没有违法所得的，由公安机关交通管理部门处二万元以下罚款。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"组织他人参加审验教育时在签注学习记录、学习过程中弄虚作假没有违法所得的，处二万元以下罚款。"},{"id":441,"type":"判断题","question":"机动车驾驶人使用其他机动车号牌、行驶证的，一次记12分。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的，一次记12分。"},{"id":442,"type":"判断题","question":"申请人隐瞒有关情况或者提供虚假材料申请校车驾驶资格的，申请人在一年内不得再次申请校车驾驶资格。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"隐瞒或者提供虚假材料申请校车，一年内不得再次申请。"},{"id":443,"type":"判断题","question":"点火开关在ON位置，发动机工作。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"点火开关在ON位置，发动机工作。"},{"id":444,"type":"判断题","question":"驾驶机动车在道路上超车时应使用转向灯。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"方向改变要提前开启转向灯。"},{"id":445,"type":"单选题","question":"驾驶机动车不得在交叉路口、铁路道口、急弯路、宽度不足4米的窄路、桥梁、陡坡、隧道以及距离上述地点多少米以内的路段停车？","options":["30","80","50","100"],"answer":[2],"image":null,"tip":"","explanation":"“口五站三”要记牢。"},{"id":446,"type":"单选题","question":"如图所示，A车正在变更车道，以下说法正确的是什么？","options":["压实线变更车道","未按规定开启转向灯","未按规定车道行驶","该车没有违法行为"],"answer":[0],"image":"img/q446.jpg","tip":"","explanation":"实线不可压，因此违法。"},{"id":447,"type":"判断题","question":"在高速公路上发生事故导致车辆无法正常行驶时，驾驶人可以拦截过往车辆帮助拖车。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"发生事故只能由救援车、清障车拖曳、牵引。"},{"id":448,"type":"判断题","question":"打开后雾灯开关，如下图所示指示灯亮起。","options":["正确","错误"],"answer":[0],"image":"img/q448.jpg","tip":"","explanation":"看图中仪表板上的灯，有纵向线且为黄色光线向右，是后雾灯。"},{"id":449,"type":"单选题","question":"如图所示，该机动车在应急车道内停车，以下说法正确的是什么？①未开启危险报警闪光灯②警告标志放置距离不足150米③车上人员未转移到安全区域","options":["①②③","①②","②③","①③"],"answer":[2],"image":"img/q449.jpg","tip":"","explanation":"图中是开了双闪的，另外两个没有做到。"},{"id":450,"type":"单选题","question":"如图所示，在这条车道行驶的最低车速是多少？","options":["60公里/小时","90公里/小时","100公里/小时","110公里/小时"],"answer":[2],"image":"img/q450.jpg","tip":"","explanation":"图中机动车在左侧车道，根据高速公路规定：同方向有2条车道的，左侧车道的最低车速为每小时100公里。注意右侧红圈白底标志为迷惑项，是最高限速标志，不是最低。"},{"id":451,"type":"判断题","question":"如图所示，通过有这种标志的路口时应该减速让行。","options":["正确","错误"],"answer":[1],"image":"img/q451.jpg","tip":"","explanation":"图中路右侧八角形一个“停”字，是停车让行标志。题干说“减速让行”是错的。"},{"id":452,"type":"单选题","question":"机动车仪表板上如图所示指示灯亮表示什么？","options":["行车制动系统出现故障","驻车制动器处于制动状态","防抱死制动系统出现故障","驻车制动器处于解除状态"],"answer":[1],"image":"img/q452.jpg","tip":"","explanation":"看图中仪表板上的灯，圆圈里有个“P”是驻车制动器处于制动状态标志。"},{"id":453,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮，提示发电机向蓄电池充电。","options":["正确","错误"],"answer":[1],"image":"img/q453.jpg","tip":"","explanation":"图中仪表板上像个电池有加减号，是电瓶指示灯，一直亮起，说明充电电路故障。"},{"id":454,"type":"单选题","question":"如图所示，在路边临时停放机动车是什么违法行为？","options":["在非机动车道停车","停车占用机动车道","距离路边超过30厘米","在有禁停标线路段停车"],"answer":[3],"image":"img/q454.jpg","tip":"","explanation":"看图中路边涂了满满的黄漆，是禁止临时或长时停放车辆线，所以不能临时停车。"},{"id":455,"type":"判断题","question":"如图所示，驾驶机动车驶出匝道后可以直接驶入行车道。","options":["正确","错误"],"answer":[1],"image":"img/q455.jpg","tip":"","explanation":"驾驶机动车进入高速公路，应该尽快在加速车道将车速提到60km/h以上，确认安全再进入主车道行驶。&nbsp;&nbsp;&nbsp;"},{"id":456,"type":"判断题","question":"如图所示，这辆小型载客汽车驶离高速公路行车道的方法是正确的。","options":["正确","错误"],"answer":[0],"image":"img/q456.jpg","tip":"","explanation":"图中车辆开启了右转向灯，并在虚线处向右进入减速车道，这种驶离高速的方法是正确的。"},{"id":457,"type":"单选题","question":"下列哪个交通标志表示不能停车？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[1],"image":"img/q457.jpg","tip":"","explanation":"图A：红圈蓝底一个“\\”，是禁止长时停放标志；图B：红圈蓝底一个“×”，是禁止停车标志；图C：红圈内有“检查”，是停车检查标志；图D：八角形一个“停”，是停车让行标志。题干问不能停车，选图B。"},{"id":458,"type":"单选题","question":"如图所示，在这个弯道上行驶时的最高速度不能超过多少？","options":["30公里/小时","40公里/小时","50公里/小时","70公里/小时"],"answer":[0],"image":"img/q458.jpg","tip":"","explanation":"图中是向右急转弯路段，最高时速为30公里/小时，车速太快易引发事故。"},{"id":459,"type":"单选题","question":"如图所示，这辆在高速公路上临时停放的故障车，警告标志应该设置在车后多远处？","options":["150米以外","50~150米","50~100米","50米以内"],"answer":[0],"image":"img/q459.jpg","tip":"","explanation":"注意这是“高速公路”，发生故障警告标志要设置在车后150米以外，普通道路则为50-100米。"},{"id":460,"type":"单选题","question":"如图所示，进入减速车道时怎样使用灯光？","options":["开启左转向灯","开启右转向灯","开启危险报警闪光灯","开启前照灯"],"answer":[1],"image":"img/q460.jpg","tip":"","explanation":"减速车道在该车行驶车道右侧，需要提前开启右转向灯示意后车避让。"},{"id":461,"type":"单选题","question":"驾驶车辆时在道路上抛撒物品，以下说法不正确的是什么？","options":["抛撒纸张等轻质物品会阻挡驾驶人视线，分散驾驶人注意力","有可能引起其他驾驶人紧急躲避等应激反应，进而引发事故","破坏环境，影响环境整洁，甚至造成路面的损坏","保持车内整洁，减少燃油消耗"],"answer":[3],"image":null,"tip":"","explanation":"行车过程中随意乱抛物品，并不能减少油耗。相反，这种行为会破坏环境，影响后方车辆正常行驶，易引发交通事故。注意是选“不正确的”。"},{"id":462,"type":"单选题","question":"人行横道上禁止掉头的原因是什么？","options":["人行横道路太窄","此路段有监控设备","避免妨碍行人正常通行，确保行人安全","人行横道禁止停车"],"answer":[2],"image":null,"tip":"","explanation":"人行横道是供行人通行的，在此处掉头会妨碍行人正常通行，有安全隐患，禁止掉头。"},{"id":463,"type":"单选题","question":"以下哪个指示灯亮时，表示油箱内燃油已到最低液面？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[3],"image":"img/q463.jpg","tip":"","explanation":"题干问燃油已到最低指示灯，图中找加油机，即图D。其他三项图A是机油指示灯，图B是前雾灯，图C是ABS指示灯。要注意选项与图片编号的对应关系。"},{"id":464,"type":"单选题","question":"如图所示，驾驶机动车遇到这种信号灯不断闪烁时怎样行驶？","options":["尽快加速通过","靠边停车等待","注意瞭望安全通过","紧急制动"],"answer":[2],"image":"img/q464.jpg","tip":"","explanation":"图中信号灯是持续闪烁的黄灯，提示车辆、行人通行时注意瞭望，确认安全后通过。"},{"id":465,"type":"判断题","question":"驾驶机动车超车应该提前开启左转向灯、变换使用远、近光灯或鸣喇叭。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"超车只能从前车左侧超越，提前开启左转向灯，并通过变换远近光灯或鸣喇叭示意。"},{"id":466,"type":"判断题","question":"有执行社区戒毒、强制隔离戒毒、社区康复措施记录的，车辆管理所将注销其驾驶证。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"毒品危害巨大，吸毒后会造成驾驶人精神恍惚，极易引发事故，无论是吸毒后还是戒毒康复期间，都要注销其驾驶证。"},{"id":467,"type":"单选题","question":"如图所示，以下哪种情况可以超车？","options":["如图中A所示","如图中B所示","如图中C所示","如图中D所示"],"answer":[2],"image":"img/q467.jpg","tip":"","explanation":"超车要满足两个条件：一是虚线一侧，二是对向无来车。如图所示，只有图C符合条件，其他情况都不允许超车。"},{"id":468,"type":"单选题","question":"如图所示，驾驶机动车遇到这种桥时首先怎样办？","options":["保持匀速通过","尽快加速通过","低速缓慢通过","停车察明水情"],"answer":[3],"image":"img/q468.jpg","tip":"","explanation":"图中右侧标志是过水路面，贸然通过车辆可能会进水，为了安全起见，要先停车察明水情，确保安全后再低速通过。"},{"id":469,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮，表示行车制动系统可能出现故障。","options":["正确","错误"],"answer":[0],"image":"img/q469.jpg","tip":"","explanation":"看图中仪表板上的灯，圆圈里有个“！”是制动系统出现异常标志。"},{"id":470,"type":"判断题","question":"机动车仪表板上如图所示指示灯亮时，提醒驾驶人座椅没调整好。","options":["正确","错误"],"answer":[1],"image":"img/q470.jpg","tip":"","explanation":"看图中仪表板上是安全带指示灯，一直亮起，说明没系好安全带。题干说“座椅”是错的。"},{"id":471,"type":"判断题","question":"夜间行车，需要超车时，变换远、近光灯示意是为了提示前车。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"夜间行车光线不足，如需要超车，要交替使用远近光灯，以提醒前车注意。"},{"id":472,"type":"判断题","question":"驾驶校车、公路客运汽车、旅游客运汽车、7座以上载客汽车以外的其他载客汽车载人超过核定人数百分之五十以上未达到百分之百的，一次记9分。","options":["正确","错误"],"answer":[1],"image":null,"tip":"","explanation":"驾驶其他载客汽车超载50%-100%之间的，一次记6分。"},{"id":473,"type":"单选题","question":"驾驶机动车下陡坡时，以下做法正确的是？","options":["熄火、空挡","熄火但不准空挡","空挡但不准熄火","不准空挡或熄火"],"answer":[3],"image":null,"tip":"","explanation":"下陡坡时不准空挡或熄火，因为车辆失去了发动机的牵制，只能靠刹车来控制车速，会造成刹车片温度升高，影响制动效果，有极大的安全隐患。"},{"id":474,"type":"单选题","question":"遇后车发出超车信号后，只要具备让超条件应怎样做？","options":["主动减速并靠左侧行驶","主动减速并靠右侧行驶","让出适当空间加速行驶","迅速减速或紧急制动"],"answer":[1],"image":null,"tip":"","explanation":"遇到后车发出超车信号，在条件许可的情况下，要减速并靠右侧行驶，文明驾驶，礼貌让行。"},{"id":475,"type":"判断题","question":"冬季给电动汽车充电前，应提前预热电池。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"低温是电池的杀手，冬季充电之前要预热电池。"},{"id":476,"type":"判断题","question":"驾驶机动车遇到后方有执行任务的紧急车辆时，可以借用无人通行的非机动车道让行。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"当遇到紧急执行任务的特种车辆时需要让行，可以临时借用无人通行的非机动车道。"},{"id":477,"type":"判断题","question":"机动车在发生碰撞时，安全带可以减轻驾乘人员受到的伤害。","options":["正确","错误"],"answer":[0],"image":null,"tip":"","explanation":"安全带的作用是在车辆发生碰撞时，固定驾驶员位置，减轻对驾驶员的伤害。为安全起见，行车前一定要先系好安全带。"},{"id":478,"type":"单选题","question":"大雾天行车，多鸣喇叭是为了什么？","options":["准备超越前车","引起对方注意，避免发生危险","催促前车让行","催促前车提速"],"answer":[1],"image":null,"tip":"","explanation":"雾天行车视线不清，就只能靠听了，适当鸣喇叭与其他车辆交流，引起对方注意，避免发生危险。"},{"id":479,"type":"单选题","question":"这个标志是何含义？","options":["高速公路停车区预告","高速公路避险处预告","高速公路服务区预告","高速公路停车场预告"],"answer":[0],"image":"img/q479.jpg","tip":"高速绿底标志：只有P，停车场；有茶杯，停车区；有刀叉，服务区。","explanation":"绿牌标志内有停车、喝水图标的，是高速公路停车区预告标志，用于预告停车区所在位置。注意区分：有加油、用餐等更多图标的是服务区。"},{"id":480,"type":"单选题","question":"驾驶机动车在高速公路遇到能见度低于100米的气象条件时，最高车速是多少？","options":["不得超过40公里/小时","不得超过60公里/小时","不得超过80公里/小时","不得超过90公里/小时"],"answer":[0],"image":null,"tip":"261，145，520。","explanation":"261、145、520（离）（261表示：能见度为200米时，限速60公里/小时，与前车要保持100米的安全距离。以此类推。） &nbsp; &nbsp;"},{"id":481,"type":"单选题","question":"驾驶机动车遇到前方低速行驶的洒水车作业时，以下做法错误的是什么？","options":["注意避让","若洒水车有指示箭头，在确保安全的情况下按箭头指示方向变更车道","若洒水车无指示箭头，在确保安全的情况下选择合适的车道变更","通过洒水车时应急加速通过"],"answer":[3],"image":null,"tip":"复杂路段减速行，遇人遇车要礼让，必要靠边停车让。","explanation":"注意是选“错误的”，经过洒水车要注意避让，“加速通过”是错的。"},{"id":482,"type":"单选题","question":"在高速公路上驾驶机动车，车辆发生故障后的处置方法，以下说法错误的是什么？","options":["打开危险报警闪光灯，夜间还应开启示廓灯、后位灯","在车后150米以外设置安全警告标志","车内乘员应下车辅助将故障车辆推移到紧急停车带上","所有人员需离开故障车辆，在紧急停车带或护栏以外安全位置报警并等候救援"],"answer":[2],"image":null,"tip":"生命安全第一，车辆发生故障后，人不能在马路逗留，题干问“错误”做法。所以选“车内乘员应下车辅助将故障车辆推移到紧急停车带上”。","explanation":"高速公路上，安全第一，推车危险。"},{"id":483,"type":"判断题","question":"驾驶机动车在没有中心线的公路上，最高速度不能超过每小时70公里。","options":["正确","错误"],"answer":[1],"image":null,"tip":"无中心线城3公4走中间；有中心线城5公7靠右边。","explanation":"没有中心线的公路，相对路面较窄，遇到会车等情况易引发事故，车速不能超越40公里/小时。"},{"id":484,"type":"判断题","question":"小型客车行驶在平坦的高速公路上，突然有颠簸感觉时，应迅速降低车速，防止爆胎。","options":["正确","错误"],"answer":[0],"image":null,"tip":"颠簸不平低挡过。","explanation":"在平坦的高速公路上，突然有颠簸感，说明轮胎可能出现问题，为防止爆胎，要先降低车速，找一个安全的地方停车检查。"},{"id":485,"type":"判断题","question":"驾驶机动车遇前方交叉路口交通阻塞时，路口内无网状线的，可停在路口内等候。","options":["正确","错误"],"answer":[1],"image":null,"tip":"路口观察减速行，拥堵依次交替走；排队停在路口外，依次停车等放行。","explanation":"路口内已经拥堵就别再“添堵”了，要在停止线外等待，不得进入。"},{"id":486,"type":"判断题","question":"驾驶有ABS系统的机动车在紧急制动的同时转向可能会发生侧滑。","options":["正确","错误"],"answer":[0],"image":null,"tip":"ABS防抱死，紧急制动用力踏，同时转向会侧滑；灯亮表示有故障。","explanation":"安装ABS系统的车辆，如果紧急制动的同时转向，是有可能发生侧滑的。"},{"id":487,"type":"单选题","question":"在同向4车道高速公路上行车，车速高于每小时110公里的车辆应在哪条车道上行驶？","options":["最左侧","第二条","最右侧","第三条"],"answer":[0],"image":null,"tip":"高速限速60至120；最低时速两道左100，三道以上左110中90。","explanation":"高速公路同方向有3条以上车道，最左侧车道最低时速为110公里，题干问车速高于每小时110公里，选项找“最左侧”。"},{"id":488,"type":"判断题","question":"准驾车型为小型汽车的，可以驾驶小型自动挡载客汽车。","options":["正确","错误"],"answer":[0],"image":null,"tip":"C1准驾2/3/4，C2可驾自动挡，年满18就能考。","explanation":"小型汽车C1，还准许驾驶小型自动挡汽车C2、低速载货汽车C3、三轮汽车C4车型。"},{"id":489,"type":"判断题","question":"车辆在高速公路匝道提速到每小时60公里以上时，可直接驶入行车道。","options":["正确","错误"],"answer":[1],"image":null,"tip":"看文字答题，题干中见到“直接”就选错。（例外情况1题：当见到“直接影响”时选对）","explanation":"提速到每小时60公里以上是在加速车道完成的，而不是匝道。"},{"id":490,"type":"判断题","question":"申请人因故不能按照预约时间参加考试的，应当提前一日申请取消预约，对申请人未按照预约考试时间参加考试的，判定该次考试不合格。","options":["正确","错误"],"answer":[0],"image":null,"tip":"考试不参加，成绩不合格。","explanation":"每次考试都要预约，因故无法参加的，要提前1天取消，否则按不合格处理。"},{"id":491,"type":"单选题","question":"同车道行驶的车辆遇前车有下列哪种情形时不得超车？","options":["正在停车","减速让行","正常行驶","正在超车"],"answer":[3],"image":null,"tip":"危险路段、对向有车、前车向左或不让、遇执行公务的特种车，不能超车。","explanation":"超车只能从前车左侧超越，如果此时前车正在超车，强行超越会发生碰撞，所以不得超车。"},{"id":492,"type":"单选题","question":"驾驶机动车遇雾、雨、雪等能见度在50米以内时，最高速度不能超过多少？","options":["70公里/小时","50公里/小时","40公里/小时","30公里/小时"],"answer":[3],"image":null,"tip":"复杂路段、特殊天气、特殊操作，限速30。","explanation":"雾、雨、雪等特殊天气能见度不足50米，严重影响行车安全，车速要控制在30公里/小时以内。"},{"id":493,"type":"判断题","question":"车辆驶离高速公路时，应当经减速车道减速后进入匝道。","options":["正确","错误"],"answer":[0],"image":null,"tip":"驶离高速，为不影响其他车辆正常行驶，应先走减速车道减速，再驶入匝道。所以选对。","explanation":"驶出高速公路过程：正常行驶车道-减速车道-匝道-高速出口。车辆一定要经减速车道进入匝道。"},{"id":494,"type":"单选题","question":"交叉路口不得倒车的原因是什么？","options":["交通警察多","交通监控设备多","车道数量少","交通情况复杂，容易造成交通堵塞甚至引发事故"],"answer":[3],"image":null,"tip":"危险路段禁止倒掉停，随时观察勿扰他车。","explanation":"交叉路口车辆行人较多，路况复杂，如果倒车，容易造成交通拥堵，引发交通事故。"},{"id":495,"type":"单选题","question":"驾驶机动车在高速公路上正常行驶，车速低于100km/h时，与同车道前车的最小距离不得少于多少米？","options":["50米","80米","100米","60米"],"answer":[0],"image":null,"tip":"","explanation":"高速上车速小于100，车距不低于50。"},{"id":496,"type":"单选题","question":"如图所示，当您车速为95km/h时，您可以在哪条车道内行驶？","options":["A车道","B车道","C车道","D车道"],"answer":[1],"image":"img/q496.jpg","tip":"","explanation":"图中车道上方的绿牌标志注明了每条车道的限速范围，A车道限速为100-120km/h，B车道限速为80-100km/h，C车道限速为60-80km/h，D车道是应急车道非紧急情况不得行车，所以车速为95km/h，应在B车道行驶。"}];
